/** Whether `runner` can run `tool`'s work: it is enabled there, installed and signed in. */
export function runsTool(
  runner: Pick<Runner, 'enabledTools' | 'tools'>,
  tool: AgentTool,
): boolean {
  return (
    toolEnabled(runner, tool) &&
    runner.tools.some(
      (item) =>
        item.kind === tool &&
        item.authenticated &&
        (!item.status || item.status === 'ready'),
    )
  );
```

</details>

