,\n    \"unreleased:create\": \"node ./scripts/unreleased.mjs create\",\n    \"unreleased:smoke\": \"node ./scripts/unreleased.mjs smoke\",\n    \"unreleased:installer-smoke\": \"node ./scripts/unreleased.mjs installer-smoke\",\n    \"unreleased:env\": \"node ./scripts/unreleased.mjs env\",\n    \"unreleased:clean\": \"node ./scripts/unreleased.mjs clean\"\n  },\n  \"devDependencies\": {\n    \"@arethetypeswrong/cli\": \"catalog:\",\n    \"@changesets/cli\": \"^3.0.1\",\n    \"@hono/node-server\": \"catalog:\",\n    \"@nocobase/app-cli\": \"workspace:*\",\n    \"@nocobase/db\": \"workspace:*\",\n    \"@nocobase/db-mssql\": \"workspace:*\",\n    \"@nocobase/db-mysql\": \"workspace:*\",\n    \"@nocobase/db-oracle\": \"workspace:*\",\n    \"@nocobase/db-postgres\": \"workspace:*\",\n    \"@nocobase/db-sqlite\": \"workspace:*\",\n    \"@nocobase/dev-config\": \"workspace:*\",\n    \"@types/node\": \"catalog:\",\n    \"eslint\": \"catalog:\",\n    \"hono\": \"catalog:\",\n    \"husky\": \"catalog:\",\n    \"knex\": \"catalog:\",\n    \"lint-staged\": \"catalog:\",\n    \"prettier\": \"catalog:\",\n    \"publint\": \"catalog:\",\n    \"tsx\": \"catalog:\",\n    \"typescript\": \"catalog:\",\n    \"vitest\": \"catalog:\",\n    \"vite\": \"catalog:\",\n    \"yaml\": \"catalog:\"\n  }\n}\n"
