      "path": "packages/libs/acp-bridge/src/catalog.ts",
      "content": "/** Browser-safe catalog shared by personal sessions and runners. Home-relative search directories are resolved by the launcher. */\nexport interface AgentLauncher {\n  /** The program's name, found in `dirs` or on PATH; on Windows, with one of PATHEXT's extensions. */\n  readonly command: string;\n  readonly args: readonly string[];\n  /** Directories searched before PATH. */\n  readonly dirs?: readonly string[];\n  /** Another program this launcher needs, such as the agent itself for an adapter fetched with npx. */\n  readonly requires?: string;\n  /**\n   * The launcher is an adapter the bridge manages: `package` at `version`, installed from npm on first use, whose\n   * program `command` is run by Node.js. The agent it `requires`, at least `minVersion`, is named to it in the\n   * environment variable `variable`. `batchFiles` says the adapter can start an agent that is a Windows batch file, as\n   * npm installs agents.\n   */\n  readonly managed?: {\n    readonly package: string;\n    readonly version: string;\n    readonly variable: string;\n    readonly minVersion: string;\n    readonly batchFiles?: boolean;\n  };\n}\n\nexport interface AgentSpec {\n  readonly id: string;\n  readonly name: string;\n  /** Ways to start it, in order of preference. */\n  readonly launchers: readonly AgentLauncher[];\n  /** The values of the session's `mode` choice that give the agent full access: a session opens in the first offered. */\n  readonly modes?: readonly string[];\n  /** The agent offers no such mode: the bridge allows whatever it asks permission for. */\n  readonly allowAll?: boolean;\n  /** What a person runs in a terminal to sign in to it, for the message when it is not signed in. */\n  readonly signIn: string;\n  /** Environment the agent runs with, over the bridge's own. */\n  readonly env?: Readonly<Record<string, string>>;\n  /** Full-access defaults for real sessions; never applied during runner detection. */\n  readonly permissionEnv?: Readonly<Record<string, string>>;\n  /**\n   * The session's `configOptions`/model-like choices are not models (Amp's are reasoning modes): the runner reports\n   * no model list for this agent rather than one entry per choice, and names its agent after the tool alone.\n   */\n  readonly modelsAreNotModels?: boolean;\n  /**\n   * Confirms a program found under this agent's expected name actually is it, before trying to speak ACP to it:\n   * run it with `args`; if the combined stdout and stderr match `reject`, the program found is something else\n   * (Goose, the AI agent, and the unrelated `pressly/goose` database migration tool share a name on PATH).\n   */\n  readonly identify?: {\n    readonly args: readonly string[];\n    readonly reject: RegExp;\n    /** Default 5000. */\n    readonly timeoutMs?: number;\n  };\n  /**\n   * A successful detection handshake (`initialize` and `session/new`) does not mean this agent is signed in: it\n   * opens a session the same way whether or not it is. Authentication methods advertise supported flows, never\n   * authentication state. Without a confirmed check below, detection reports failure rather than guessing.\n   */\n  readonly signInUnconfirmable?: boolean;\n  /** A reviewed, noninteractive authentication check, restricted to the implementation versions reviewed. */\n  readonly authenticationCheck?: {\n    readonly agentName: string;\n    readonly versions: readonly string[];\n    readonly methodId: string;\n    readonly unconfirmedDetail: string;\n  };\n}\n\nconst localBin = '~/.local/bin';\n\n/** The program `command` run with `args`, found as it is installed. */\nfunction program(\n  command: string,\n  args: readonly string[] = [],\n  dirs: readonly string[] = [],\n): AgentLauncher {\n  return { command, args, ...(dirs.length > 0 ? { dirs } : {}) };\n}\n\n/** The adapter versions the bridge installs. */\nconst CODEX_ACP = { name: '@agentclientprotocol/codex-acp', version: '2.2.2' };\nconst CLAUDE_AGENT_ACP = {\n  name: '@agentclientprotocol/claude-agent-acp',\n  version: '0.89.1',\n};\n\n/**\n * The ACP adapter `adapter`, whose program `bin` runs the agent `requires` that it finds in `variable`: managed by the\n * bridge, unless installed on PATH. The adapter is built against `minVersion` of the agent and may\n * not drive an older one.\n */\nfunction adapter(\n  pkg: { readonly name: string; readonly version: string },\n  bin: string,\n  requires: string,\n  agent: Omit<NonNullable<AgentLauncher['managed']>, 'package' | 'version'>,\n): AgentLauncher[] {\n  return [\n    program(bin),\n    {\n      command: bin,\n      args: [],\n      requires,\n      managed: { package: pkg.name, version: pkg.version, ...agent },\n    },\n  ];\n}\n\n/** The agents the bridge offers, the most used first. */\nexport const CATALOG_IDS = [\n  'codex',\n  'claude',\n  'gemini',\n  'copilot',\n  'cursor',\n  'opencode',\n  'qwen',\n  'kimi',\n  'codebuddy',\n  'qoder',\n  'goose',\n  'auggie',\n  'droid',\n  'kilo',\n  'cline',\n  'amp',\n  'vibe',\n  'dsh',\n] as const;\nexport type CatalogAgentId = (typeof CATALOG_IDS)[number];\nexport const AGENTS: readonly (AgentSpec & { readonly id: CatalogAgentId })[] =\n  [\n    {\n      id: 'codex',\n      name: 'Codex',\n      // codex-acp starts Codex with cross-spawn, which runs npm's `codex.cmd` on Windows.\n      launchers: adapter(CODEX_ACP, 'codex-acp', 'codex', {\n        variable: 'CODEX_PATH',\n        minVersion: '0.160.1',\n        batchFiles: true,\n      }),\n      modes: ['agent-full-access'],\n      signIn: 'codex login',\n    },\n    {\n      id: 'claude',\n      name: 'Claude Code',\n      launchers: adapter(CLAUDE_AGENT_ACP, 'claude-agent-acp', 'claude', {\n        variable: 'CLAUDE_CODE_EXECUTABLE',\n        minVersion: '2.1.200',\n      }),\n      modes: ['bypassPermissions'],\n      signIn: 'claude',\n    },\n    {\n      id: 'gemini',\n      name: 'Gemini CLI',\n      launchers: [program('gemini', ['--acp'])],\n      modes: ['yolo'],\n      signIn: 'gemini',\n    },\n    {\n      id: 'copilot',\n      name: 'GitHub Copilot',\n      launchers: [program('copilot', ['--acp'])],\n      allowAll: true,\n      signIn: 'copilot',\n    },\n    {\n      id: 'cursor',\n      name: 'Cursor',\n      launchers: [program('cursor-agent', ['acp'], [localBin])],\n      allowAll: true,\n      signIn: 'cursor-agent login',\n    },\n    {\n      id: 'opencode',\n      name: 'OpenCode',\n      launchers: [program('opencode', ['acp'], ['~/.opencode/bin'])],\n      modes: ['build'],\n      signIn: 'opencode auth login',\n      permissionEnv: {\n        OPENCODE_PERMISSION: JSON.stringify({\n          edit: 'allow',\n          bash: 'allow',\n          webfetch: 'allow',\n          external_directory: 'allow',\n        }),\n      },\n    },\n    {\n      id: 'qwen',\n      name: 'Qwen Code',\n      launchers: [program('qwen', ['--acp'])],\n      modes: ['yolo'],\n      signIn: 'qwen',\n    },\n    {\n      id: 'kimi',\n      name: 'Kimi CLI',\n      launchers: [program('kimi', ['acp'], [localBin])],\n      allowAll: true,\n      signIn: 'kimi',\n    },\n    {\n      id: 'codebuddy',\n      name: 'CodeBuddy Code',\n      launchers: [program('codebuddy', ['--acp'])],\n      allowAll: true,\n      signIn: 'codebuddy',\n    },\n    {\n      id: 'qoder',\n      name: 'Qoder CLI',\n      launchers: [program('qodercli', ['--acp'])],\n      allowAll: true,\n      signIn: 'qodercli',\n    },\n    {\n      id: 'goose',\n      name: 'Goose',\n      launchers: [program('goose', ['acp'], [localBin])],\n      allowAll: true,\n      signIn: 'goose configure',\n      permissionEnv: { GOOSE_MODE: 'auto' },\n      identify: {\n        args: ['--help'],\n        // The unrelated `pressly/goose` database migration CLI of the same name documents these subcommands and\n        // flags (`up`, `down`, `-dir`, a DSN); the AI agent's own CLI vocabulary (session, acp, mcp, configure,\n        // recipe) does not use them. A negative match, not a positive one: it only rejects the known other\n        // program, so an agent CLI surface this list has not seen still passes. Not verified against either\n        // program's real --help output in this environment.\n        reject: /\\bdbstring\\b|-dir string|\\bup-by-one\\b|\\bgoose:\\s*version\\b/iu,\n      },\n    },\n    {\n      id: 'auggie',\n      name: 'Auggie',\n      launchers: [program('auggie', ['--acp'])],\n      allowAll: true,\n      signIn: 'auggie login',\n      env: { AUGMENT_DISABLE_AUTO_UPDATE: '1' },\n    },\n    {\n      id: 'droid',\n      name: 'Factory Droid',\n      launchers: [\n        program(\n          'droid',\n          ['exec', '--output-format', 'acp-daemon'],\n          [localBin, '~/.factory/bin'],\n        ),\n      ],\n      allowAll: true,\n      signIn: 'droid',\n      env: {\n        DROID_DISABLE_AUTO_UPDATE: 'true',\n        FACTORY_DROID_AUTO_UPDATE_ENABLED: 'false',\n      },\n    },\n    {\n      id: 'kilo',\n      name: 'Kilo Code',\n      launchers: [program('kilo', ['acp'])],\n      allowAll: true,\n      signIn: 'kilo',\n    },\n    {\n      id: 'cline',\n      name: 'Cline',\n      launchers: [program('cline', ['--acp'])],\n      allowAll: true,\n      signIn: 'cline',\n    },\n    {\n      id: 'amp',\n      name: 'Amp',\n      launchers: [program('amp-acp', [], [localBin])],\n      allowAll: true,\n      signIn: 'amp login',\n      // Amp's ACP session reports its reasoning modes (low/medium/high/ultra) as configOptions, not models.\n      modelsAreNotModels: true,\n      // A successful handshake happens whether or not Amp is signed in; see `AgentSpec.signInUnconfirmable`.\n      signInUnconfirmable: true,\n      // v0.9.0/src/server.ts:218 checks only the adapter's configured API key, without launching login or a prompt.\n      // Its CLI-account fallback is not checked; AUTH_REQUIRED therefore leaves that account's state unknown.\n      authenticationCheck: {\n        agentName: 'amp-acp',\n        versions: ['0.9.0'],\n        methodId: 'setup',\n        unconfirmedDetail:\n          'The adapter could not confirm an API-key configuration; native CLI login is unconfirmed. Configure the adapter with amp-acp --setup or its supported AMP_API_KEY environment, then detect again.',\n      },\n    },\n    {\n      id: 'vibe',\n      name: 'Mistral Vibe',\n      launchers: [program('vibe-acp', [], [localBin])],\n      allowAll: true,\n      signIn: 'vibe',\n    },\n    {\n      id: 'dsh',\n      name: 'DeepSeek Harness',\n      launchers: [program('dsh', ['--profile', 'acp'])],\n      allowAll: true,\n      signIn: 'export DEEPSEEK_API_KEY=...',\n      permissionEnv: { DSH_PERMISSION_MODE: 'danger-full-access' },\n    },\n  ];\n"
    },
    {
      "path": "packages/plugins/app-plugin-agents/client/pages/runtimes/runner-overview.tsx",
      "content": "import { noCodingToolsFound } from '../../lib/runner-tools.js';\n/** Overview settings preserve drafts while the other tabs load independently. */\nimport { useTranslation } from '@nocobase/i18n/client';\nimport { useState, type FormEvent, type ReactElement } from 'react';\nimport { AGENT_TOOLS, type AgentTool } from '@nocobase/agent-protocol';\nimport {\n  jobKindsOf,\n  RUNNER_TRUST,\n  toolEnabled,\n  type RunnerPatch,\n  type RunnerSummary,\n  type RunnerTrust,\n} from '../../../shared/runners.js';\nimport { AgSection } from '../../components/ag-section.js';\nimport { AgTag } from '../../components/ag-tag.js';\nimport {\n  AlertDialog,\n  AlertDialogAction,\n  AlertDialogCancel,\n  AlertDialogContent,\n  AlertDialogDescription,\n  AlertDialogFooter,\n  AlertDialogHeader,\n  AlertDialogTitle,\n} from '../../components/ui/alert-dialog.js';\nimport {\n  Field,\n  FieldContent,\n  FieldDescription,\n  FieldError,\n  FieldGroup,\n  FieldLabel,\n  FieldLegend,\n  FieldSet,\n} from '../../components/ui/field.js';\nimport { Input } from '../../components/ui/input.js';\nimport { RadioGroup, RadioGroupItem } from '../../components/ui/radio-group.js';\nimport { Switch } from '../../components/ui/switch.js';\nimport { POLICY_FIELDS, policyRule } from './runner-policy.js';\nimport {\n  readToolSlots,\n  toolSlotsDraft,\n  type ToolSlotsDraft,\n} from '../../lib/tool-slots.js';\nimport { OverTotalHint } from './tool-slots-fields.js';\nimport { ToolTable } from './runner-tools.js';\n\nexport function RunnerOverview({\n  runner,\n  editable,\n  onSave,\n  now,\n}: {\n  readonly runner: RunnerSummary;\n  readonly editable: boolean;\n  readonly onSave: (patch: RunnerPatch) => void;\n  readonly now: number;\n}): ReactElement {\n  const { t } = useTranslation();\n  return (\n    <div className='space-y-6'>\n      <SettingsForm\n        runner={runner}\n        editable={editable}\n        onSave={onSave}\n        now={now}\n      />\n      <AgSection\n        className='max-w-none'\n        id='ag-runner-policy'\n        title={t('runtimes.policy.title')}\n        description={t('runtimes.policy.description')}\n      >\n        <PolicyView runner={runner} />\n      </AgSection>\n      <AgSection\n        className='max-w-none'\n        id='ag-runner-variables'\n        title={t('runtimes.variables.title')}\n        description={t('runtimes.variables.description')}\n      >\n        <VariablesView runner={runner} />\n      </AgSection>\n    </div>\n  );\n}\nfunction enabledToolsOf(\n  _runner: RunnerSummary,\n  switched: ReadonlySet<AgentTool>,\n): AgentTool[] {\n  return AGENT_TOOLS.filter((tool) => switched.has(tool));\n}\n\nfunction SettingsForm({\n  runner,\n  editable,\n  onSave,\n  now,\n}: {\n  readonly runner: RunnerSummary;\n  readonly editable: boolean;\n  readonly onSave: (patch: RunnerPatch) => void;\n  readonly now: number;\n}): ReactElement {\n  const { t } = useTranslation();\n  const [name, setName] = useState(runner.name);\n  const [slots, setSlots] = useState(String(runner.slots));\n  const [trust, setTrust] = useState<RunnerTrust>(runner.trust);\n  const [acceptJobs, setAcceptJobs] = useState(runner.acceptJobs);\n  const [toolSlots, setToolSlots] = useState<ToolSlotsDraft>(() =>\n    toolSlotsDraft(runner.toolSlots ?? null),\n  );\n  const [switched, setSwitched] = useState<ReadonlySet<AgentTool>>(\n    () => new Set(AGENT_TOOLS.filter((tool) => toolEnabled(runner, tool))),\n  );\n  const [errors, setErrors] = useState<{\n    name?: string;\n    slots?: string;\n    toolSlots?: boolean;\n  }>({});\n  // Every supported tool stays selectable, including one that has not been installed yet.\n  const limitTools = AGENT_TOOLS;\n  const [sharing, setSharing] = useState<RunnerPatch | null>(null);\n  const jobKinds = jobKindsOf(runner);\n\n  function submit(event: FormEvent<HTMLFormElement>): void {\n    event.preventDefault();\n    const count = Number(slots);\n    const limits = readToolSlots(toolSlots, limitTools);\n    const found = {\n      ...(name.trim() ? {} : { name: t('runtimes.edit.nameRequired') }),\n      ...(Number.isInteger(count) && count >= 1 && count <= 64\n        ? {}\n        : { slots: t('runtimes.edit.slotsInvalid') }),\n      ...(limits === undefined ? { toolSlots: true } : {}),\n    };\n    setErrors(found);\n    if (Object.keys(found).length > 0) return;\n    const patch: RunnerPatch = {\n      ...(name.trim() === runner.name ? {} : { name: name.trim() }),\n      ...(count === runner.slots ? {} : { slots: count }),\n      ...(limits === undefined ||\n      JSON.stringify(limits) === JSON.stringify(runner.toolSlots ?? null)\n        ? {}\n        : { toolSlots: limits }),\n      ...(trust === runner.trust ? {} : { trust }),\n      ...(acceptJobs === runner.acceptJobs ? {} : { acceptJobs }),\n      ...(JSON.stringify(enabledToolsOf(runner, switched)) ===\n      JSON.stringify(\n        enabledToolsOf(\n          runner,\n          new Set(AGENT_TOOLS.filter((tool) => toolEnabled(runner, tool))),\n        ),\n      )\n        ? {}\n        : { enabledTools: enabledToolsOf(runner, switched) }),\n    };\n    if (Object.keys(patch).length === 0) return;\n    // Sharing with the team lets other people's runs onto it: it asks first.\n    if (patch.trust === 'team') setSharing(patch);\n    else onSave(patch);\n  }\n\n  return (\n    <form\n      id='runtime-settings'\n      onSubmit={submit}\n      noValidate\n      className='space-y-6'\n    >\n      <AgSection\n        className='max-w-none'\n        id='ag-runner-general'\n        title={t('runtimes.detail.general')}\n      >\n        <FieldGroup className='sm:grid sm:grid-cols-2'>\n          <Field data-invalid={errors.name ? true : undefined}>\n            <FieldLabel htmlFor='ag-runner-name'>\n              {t('runtimes.edit.name')}\n            </FieldLabel>\n            <Input\n              id='ag-runner-name'\n              value={name}\n              maxLength={200}\n              disabled={!editable}\n              aria-invalid={errors.name ? true : undefined}\n              onChange={(event) => setName(event.target.value)}\n            />\n            {errors.name ? <FieldError>{errors.name}</FieldError> : null}\n          </Field>\n          <Field data-invalid={errors.slots ? true : undefined}>\n            <FieldLabel htmlFor='ag-runner-slots'>\n              {t('connect.slots')}\n            </FieldLabel>\n            <Input\n              id='ag-runner-slots'\n              inputMode='numeric'\n              value={slots}\n              disabled={!editable}\n              aria-invalid={errors.slots ? true : undefined}\n              onChange={(event) => setSlots(event.target.value)}\n            />\n            {errors.slots ? (\n              <FieldError>{errors.slots}</FieldError>\n            ) : (\n              <FieldDescription>\n                {t('runtimes.edit.slotsHint')}\n              </FieldDescription>\n            )}\n          </Field>\n          <FieldSet className='sm:col-span-2'>\n            <FieldLegend variant='label'>\n              {t('runtimes.trust.label')}\n            </FieldLegend>\n            <RadioGroup\n              className='sm:grid sm:grid-cols-2'\n              value={trust}\n              disabled={!editable || !runner.canChangeTrust}\n              onValueChange={(value) => {\n                const next = RUNNER_TRUST.find((level) => level === value);\n                if (next) setTrust(next);\n              }}\n            >\n              {(['ownerOnly', 'team'] as const).map((level) => (\n                <Field\n                  key={level}\n                  orientation='horizontal'\n                  className={`rounded-lg border p-3 ${trust === level ? 'border-primary/40 bg-primary/5' : ''}`}\n                >\n                  <RadioGroupItem\n                    value={level}\n                    id={`ag-runner-trust-${level}`}\n                  />\n                  <FieldContent>\n                    <FieldLabel htmlFor={`ag-runner-trust-${level}`}>\n                      {t(`runtimes.trust.${level}`)}\n                    </FieldLabel>\n                    <FieldDescription>\n                      {t(`runtimes.trust.${level}Hint`)}\n                    </FieldDescription>\n                  </FieldContent>\n                </Field>\n              ))}\n            </RadioGroup>\n            <FieldDescription>\n              {t('runtimes.trust.isolationHint')}\n            </FieldDescription>\n          </FieldSet>\n          {runner.offersJobs ? (\n            <Field orientation='horizontal'>\n              <Switch\n                id='ag-runner-jobs'\n                checked={acceptJobs}\n                disabled={\n                  !editable || (jobKinds.length === 0 && !runner.acceptJobs)\n                }\n                onCheckedChange={setAcceptJobs}\n              />\n              <FieldContent>\n                <FieldLabel htmlFor='ag-runner-jobs'>\n                  {t('runtimes.jobs.allow')}\n                </FieldLabel>\n                <FieldDescription>\n                  {jobKinds.length > 0\n                    ? t('runtimes.jobs.hint', { kinds: jobKinds.join(', ') })\n                    : t('runtimes.jobs.unsupported')}\n                </FieldDescription>\n              </FieldContent>\n            </Field>\n          ) : null}\n        </FieldGroup>\n      </AgSection>\n      <AgSection\n        className='max-w-none'\n        id='ag-runner-tools'\n        title={t('runtimes.detail.tools')}\n        description={t('runtimes.detail.toolsDescription')}\n      >\n        {noCodingToolsFound(runner) ? (\n          <p className='mb-3 text-sm text-muted-foreground'>\n            {t('runtimes.pathHint')}\n          </p>\n        ) : null}\n        <ToolTable\n          runner={runner}\n          now={now}\n          tools={limitTools}\n          switched={switched}\n          limits={toolSlots}\n          invalid={errors.toolSlots === true}\n          editable={editable}\n          onSwitch={(tool, on) =>\n            setSwitched(\n              new Set(\n                AGENT_TOOLS.filter((candidate) =>\n                  candidate === tool ? on : switched.has(candidate),\n                ),\n              ),\n            )\n          }\n          onLimits={setToolSlots}\n        />\n        {errors.toolSlots ? (\n          <p className='mt-2 text-sm text-destructive' role='alert'>\n            {t('runtimes.toolSlots.invalid')}\n          </p>\n        ) : null}\n        <div className='mt-2'>\n          <OverTotalHint tools={limitTools} draft={toolSlots} total={slots} />\n        </div>\n      </AgSection>\n\n      <AlertDialog\n        open={sharing !== null}\n        onOpenChange={(open) => {\n          if (!open) setSharing(null);\n        }}\n      >\n        <AlertDialogContent>\n          <AlertDialogHeader>\n            <AlertDialogTitle>\n              {t('runtimes.share.title', { name: runner.name })}\n            </AlertDialogTitle>\n            <AlertDialogDescription>\n              {t('runtimes.share.description')}\n            </AlertDialogDescription>\n          </AlertDialogHeader>\n          <AlertDialogFooter>\n            <AlertDialogCancel>{t('actions.cancel')}</AlertDialogCancel>\n            <AlertDialogAction\n              onClick={() => {\n                if (sharing) onSave(sharing);\n                setSharing(null);\n              }}\n            >\n              {t('runtimes.share.confirm')}\n            </AlertDialogAction>\n          </AlertDialogFooter>\n        </AlertDialogContent>\n      </AlertDialog>\n    </form>\n  );\n}\n\nfunction PolicyView({\n  runner,\n}: {\n  readonly runner: RunnerSummary;\n}): ReactElement {\n  const { t } = useTranslation();\n  const { policy } = runner;\n  if (!policy)\n    return (\n      <p className='text-sm text-muted-foreground'>\n        {t('runtimes.policy.none')}\n      </p>\n    );\n  return (\n    <dl className='grid grid-cols-[auto_1fr] gap-x-4 gap-y-2 text-sm'>\n      {POLICY_FIELDS.map((field) => {\n        const rule = policyRule(policy, field);\n        return (\n          <div key={field} className='contents'>\n            <dt className='text-muted-foreground'>\n              {t(`runtimes.policy.${field}`)}\n            </dt>\n            <dd className='flex min-w-0 flex-wrap gap-1'>\n              {rule.kind === 'only' ? (\n                rule.patterns.map((pattern) => (\n                  <AgTag key={pattern} tone='grey' className='font-mono'>\n                    {pattern}\n                  </AgTag>\n                ))\n              ) : (\n                <span\n                  className={\n                    rule.kind === 'nothing' ? 'text-destructive' : undefined\n                  }\n                >\n                  {t(`runtimes.policy.${rule.kind}`)}\n                </span>\n              )}\n            </dd>\n          </div>\n        );\n      })}\n    </dl>\n  );\n}\n\n/** The names of the variables the runner provides to runs that take them from it, as it reported them; read only. */\nfunction VariablesView({\n  runner,\n}: {\n  readonly runner: RunnerSummary;\n}): ReactElement {\n  const { t } = useTranslation();\n  const names = runner.variables;\n  if (!names || names.length === 0)\n    return (\n      <p className='text-sm text-muted-foreground'>\n        {names ? t('runtimes.variables.none') : t('runtimes.variables.unknown')}\n      </p>\n    );\n  return (\n    <div className='flex flex-wrap gap-1' data-runner-variables>\n      {names.map((name) => (\n        <AgTag key={name} tone='grey' className='font-mono'>\n          {name}\n        </AgTag>\n      ))}\n    </div>\n  );\n}\n"
    },
    {
      "path": "packages/app/agent-runner/src/agent/worker.ts",
      "content": "import { OutputWriter } from './output-writer.ts';\nimport { PreviewTransport } from './preview-transport.ts';\nimport { existsSync } from 'node:fs';\nimport { protectUpgradeWorkspace } from '../core/workspace-use.ts';\nimport { taskSessionWorkDir } from '../core/run-worktrees.ts';\n// One run, start to end, in its own process (see supervisor.ts):\n//\n//   prepare (prepare/index.ts: workspace, application CLI, working directories, skills) -> start\n//     -> adapter turns (events, permissions, inputs) -> complete | fail | cancelAck\n//\n// The agent starts in the run's primary working directory (or the subject's work directory when the run names none),\n// with the real HOME of the user the runner runs as, its own private TMPDIR outside shared code and an external\n// Codex CODEX_HOME, the application's CLI first on its PATH and the runner's commit hook as its git hooks. Nothing restricts what its\n// tools do: the runner is not a security boundary, so run it as a dedicated user, in a container or in a VM.\n//\n// While it runs, the lease is renewed every 15 s and the run's status is polled every few seconds; both answers carry\n// the cancel flag and the unhandled inputs. An input that arrives mid-turn is steered into the turn when the adapter\n// can; otherwise it waits for the turn to end and starts the next one. `complete` must cover every input, so a\n// `RUN_INPUT_PENDING` answer means another turn.\n//\n// How a run ends:\n// - cancel requested: abort the tool, deliver the events, `cancelAck`;\n// - lease lost: abort the tool and stop; the run is no longer this runner's, so nothing is reported;\n// - SIGTERM (the runner is stopping): abort the tool and `fail(runnerOffline)` so the server can requeue the run;\n// - no event for `idleTimeoutMs`: abort the tool and `fail(idleTimeout)`.\n//\n// Nothing leaves the worker unredacted (`runSecrets`): every event is redacted as it is spooled, and so are the\n// summary, the failure detail, the repositories' push failures and the worker's log lines. The redactor removes the\n// values of the secrets the run was given (its variables, the passthrough values taken from this host, the proxy and\n// `--pass-env` values the runner passes, its CLI credential's tokens, the runner key, and every repository credential\n// as the broker gets it) and the common secret patterns of `@nocobase/agent-protocol`.\n//\n// The run's repository credentials (`workspace.git`) are kept by a broker in this process (git-credentials.ts), which\n// the checkout, the agent's git (through the runner's credential helper and a socket only this worker serves) all ask; it is closed, and the socket removed, when the run ends or is no longer this runner's.\nimport { mkdir } from 'node:fs/promises';\nimport path from 'node:path';\n\nimport type {\n  AdapterEvent,\n  AdapterHandle,\n  AdapterResult,\n  AgentAdapter,\n  PermissionCheck,\n} from './adapters/types.ts';\nimport {\n  runnerClient,\n  type AppConnection,\n  type RunnerSettings,\n} from '../lib/config.ts';\nimport {\n  backoff,\n  dataOf,\n  delay,\n  ApiError,\n  type ApiClient,\n} from '../lib/http.ts';\nimport type { RunnerPaths } from '../lib/home.ts';\nimport {\n  createRedactor,\n  FailureReasonSchema,\n  RUNNER_ROUTES,\n  routePath,\n  StatusResponseSchema,\n  EventsResponseSchema,\n  WORKSPACE_INIT_PLACEHOLDER,\n  WORKSPACE_NOTES_PLACEHOLDER,\n  type RepoReport,\n  type RunInput,\n  type RunPayload,\n  type AgentTool,\n  type Usage,\n  type FailureReason,\n  type Redactor,\n} from '../protocol/index.ts';\nimport {\n  markDirsPrepared,\n  markWorkspaceEnded,\n  readWorkspaceMeta,\n  writeWorkspaceMeta,\n  reportRepos,\n  RUNNER_DIR,\n  type PreparedDir,\n} from '../core/checkout.ts';\nimport { deleteRunCredentials } from './credentials.ts';\nimport { prepareCodexHome } from './codex-home.ts';\nimport { SKILLS_PLUGIN_NAME } from './skills.ts';\nimport { buildAgentEnv, environmentSecrets, providedVariables } from './env.ts';\nimport {\n  allocateRunTemp,\n  removeRunTemp,\n  type RunTemp,\n} from '../core/run-temp.ts';\nimport {\n  GitCredentialBroker,\n  installCredentialHelper,\n  serveGitCredentials,\n  type CredentialServer,\n} from './git-credentials.ts';\nimport { PROCESS_TAG_ENV } from '../core/process-tree.ts';\nimport { QuotaReportSchema, type QuotaReport } from '@nocobase/agent-protocol';\nimport { EventSpool } from '../core/events.ts';\nimport { isDiskFull } from '../lib/disk-full.ts';\nimport { LeaseKeeper, LOST_CODES } from '../core/lease.ts';\nimport { ensurePnpmStore } from '../core/pnpm-store.ts';\nimport { writeRunnerTools } from './runner-tools.ts';\nimport { removeHostToolWrappers, writeHostTools } from './host-tools.ts';\nimport {\n  agentCwd,\n  PREPARE_STEPS,\n  PrepareError,\n  stepFailure,\n  type PrepareContext,\n} from './prepare/index.ts';\nimport {\n  removeRecord,\n  writeRecord,\n  type RunRecord,\n  type Timings,\n} from '../core/supervisor.ts';\n\nexport interface WorkerDeps {\n  paths: RunnerPaths;\n  /** The registration the run was claimed through. */\n  connection: AppConnection;\n  settings: RunnerSettings;\n  adapters: Map<AgentTool, AgentAdapter>;\n  /** Version from background detection; starting a task must not launch an inspection. */\n  toolVersion?: string;\n  log: (message: string) => void;\n  /** Overrides the client built from `connection`, for tests. */\n  client?: ApiClient;\n  /** Stops this isolated worker's descendants before ending this run. */\n  stopWriters?: () => Promise<void>;\n}\n\nexport type WorkerOutcome =\n  'completed' | 'failed' | 'cancelled' | 'leaseLost' | 'stopped';\n\ntype Ending =\n  | { kind: 'upgrade' }\n  | { kind: 'cancel' }\n  | { kind: 'lost'; code: string }\n  | { kind: 'shutdown' }\n  | { kind: 'idle' };\n\n/** The system prompt, with what only the runner knows put where the application asked for it. */\nexport function systemPrompt(\n  system: string,\n  notes: string,\n  init: string = '',\n): string {\n  const fill = (text: string, placeholder: string, value: string): string =>\n    text.includes(placeholder) ? text.split(placeholder).join(value) : text;\n  return fill(\n    fill(system, WORKSPACE_NOTES_PLACEHOLDER, notes),\n    WORKSPACE_INIT_PLACEHOLDER,\n    init,\n  ).replace(/\\n{3,}/gu, '\\n\\n');\n}\n\n/** What the runner tells the agent about its working directories. */\nexport function workspaceNotes(options: {\n  workDir: string;\n  tmpDir: string;\n  cwd: string;\n  dirs: readonly PreparedDir[];\n  cli: string;\n  skillsDir?: string;\n  /** The coding tool, for how it names the skills. */\n  tool?: AgentTool;\n  /** Directories of files the application placed for this run, with what each holds. */\n  mounts?: readonly { readonly dir: string; readonly note?: string }[];\n  /** The pnpm store every run on this machine shares. */\n  pnpmStoreDir?: string;\n  /** The run only reads (`workspace.readOnly`): nothing it commits is pushed. */\n  readOnly?: boolean;\n}): string {\n  const { workDir, cwd, dirs, tmpDir } = options;\n  const lines = [\n    dirs.length === 0\n      ? `Your working directory is ${workDir}, an empty directory kept for this task; you start in it.`\n      : `You start in ${cwd}. The runner keeps this task's own files in ${workDir}.`,\n  ];\n  lines.push(\n    `TMPDIR, TMP and TEMP point to ${tmpDir}, which you and your child processes may write.`,\n    'All runs of this task share a fixed workspace on this machine, including other agents and read-only runs. Coordinate concurrent changes yourself. Each agent resumes its own session here; old attempt directories and sessions are not migrated.',\n  );\n  if (dirs.length > 0) {\n    lines.push(\n      `Keep drafts and temporary tools outside repositories, in the task's temporary directory (${tmpDir}). The runner preserves code, uncommitted changes, dependencies and build artifacts when a run ends or is interrupted. Commit and push your own work explicitly; the runner never commits or pushes for you. Run-private temporary files are removed.`,\n    );\n    lines.push('Working directories (the first is the primary one):');\n    for (const dir of dirs) {\n      const name = dir.name === undefined ? '' : ` (${dir.name})`;\n      lines.push(\n        dir.repo === undefined\n          ? `- ${dir.dir}${name}: a directory used in place, not a checkout; there is no branch to push, so leave version control to the people who own it.`\n          : options.readOnly === true\n            ? `- ${dir.dir}${name}: ${dir.repo.url}, branch ${dir.repo.branch} from ${dir.repo.defaultBranch} (a shared workspace for a read-only run: change no tracked file, commit and push nothing).`\n            : `- ${dir.dir}${name}: ${dir.repo.url}, starting target branch ${dir.repo.branch} from ${dir.repo.defaultBranch}, local branch ${dir.repo.localBranch ?? dir.repo.branch}. You may switch or create branches and push any branch of this repository after checking the current branch, with git push origin HEAD:refs/heads/<branch> (requested initial target: ${dir.repo.branch}). Never rewrite already-pushed history or force push. Open and update change requests (pull or merge requests) with the code host's command line, such as gh, glab or gitee, when one is available; ${options.cli} pr link and pr unlink manage the task's other associations. Check each command's --help for arguments.`,\n      );\n    }\n    for (const dir of dirs)\n      for (const warning of dir.repo?.warnings ?? []) lines.push(warning);\n    if (options.readOnly === true)\n      lines.push(\n        'This step only reads: another run may be changing the same branch in this same directory at the same time. Change no tracked file, commit and push nothing; the runner pushes nothing from this checkout. You may still prepare the checkout to run things here: initialize submodules, install dependencies, build, start the application and run checks.',\n      );\n    for (const dir of dirs) {\n      if (dir.repo?.initializing)\n        lines.push(\n          `The remote ${dir.repo.url} has no refs. This checkout is initializing it on ${dir.repo.branch}, with no base commit. Implement the task in this directory, verify the result, then commit and push this branch. This first delivery needs no pull request, even if the usual workflow asks for one: there is no base branch yet. The push may only create the branch, not overwrite a branch created by someone else. Preserve existing files and commits on a retry. Report the actual checks and any failure; do not claim the task is complete merely because the first push succeeded.`,\n        );\n    }\n    lines.push(\n      `Keep every file you write inside these directories or the task's temporary directory (${tmpDir}).`,\n    );\n  }\n  if (options.pnpmStoreDir !== undefined)\n    lines.push(\n      `pnpm is set up to use this machine's shared store, ${options.pnpmStoreDir}, which you may write: install with a plain \\`pnpm install\\`, without \\`--store-dir\\`, so dependencies come from it instead of being downloaded again. Never change the store's files.`,\n      'Dependencies under `node_modules` are hard links into that store, shared by every run on this machine: never edit them in place. To change a dependency for debugging, use `pnpm patch <pkg>` (edit the extracted copy, then `pnpm patch-commit` or discard it), or copy the file elsewhere.',\n    );\n  if (options.skillsDir !== undefined)\n    lines.push(\n      `Your skills are in ${options.skillsDir}, one directory each with its SKILL.md; read a skill's SKILL.md when its description fits what you are doing.`,\n    );\n  // Claude Code knows them by their plugin's name only (`Skill(\"release-notes\")` is refused); see src/agent/skills.ts.\n  if (options.skillsDir !== undefined && options.tool === 'claude')\n    lines.push(\n      `With the Skill tool, name a skill with the \\`${SKILLS_PLUGIN_NAME}:\\` prefix, such as \\`${SKILLS_PLUGIN_NAME}:<skill name>\\`.`,\n    );\n  if (options.mounts !== undefined && options.mounts.length > 0) {\n    lines.push('Files the application placed for this run:');\n    for (const mount of options.mounts)\n      lines.push(`- ${mount.dir}${mount.note ? `: ${mount.note}` : ''}`);\n  }\n  lines.push(\n    `\\`${options.cli}\\` is on your PATH; run \\`${options.cli} --help\\` for what it can do.`,\n  );\n  return lines.join('\\n');\n}\n\n/** The initialization prompts of the directories prepared fresh for this run; empty when there are none. */\nexport function workspaceInit(dirs: readonly PreparedDir[]): string {\n  return dirs\n    .filter((dir) => dir.fresh && dir.initPrompt !== undefined)\n    .map(\n      (dir) =>\n        `This working directory was just prepared for this task. Before you start working, do the following in ${dir.dir}:\\n\\n${dir.initPrompt!.trim()}`,\n    )\n    .join('\\n\\n');\n}\n\nexport function formatInputs(inputs: readonly RunInput[]): string {\n  return inputs\n    .map(\n      (input) =>\n        `[${input.type} from ${input.actor.name} at ${input.at}]\\n${input.text}`,\n    )\n    .join('\\n\\n');\n}\n\n/** Credential fields whose values are secrets, in a run's CLI credential. */\nconst CREDENTIAL_SECRET = /token|key|secret|password/iu;\n\n/**\n * The secret values a run carries: its variables, the values of the passthrough names as this host has them, the\n * values the runner passes from its environment (its proxies, which may hold a password, and `--pass-env`), the\n * secret fields of its CLI credential (the run token), and the runner key it was claimed with.\n */\nexport function runSecrets(\n  payload: Pick<RunPayload, 'workspace' | 'cli'>,\n  connection?: Pick<AppConnection, 'runnerKey' | 'registration'>,\n  source: NodeJS.ProcessEnv = process.env,\n  passEnv: readonly string[] = [],\n): string[] {\n  const secrets = payload.workspace.env.map((variable) => variable.value);\n  const provided = providedVariables(\n    source,\n    passEnv,\n    connection?.registration.variables,\n  );\n  for (const name of payload.workspace.passthrough ?? []) {\n    const value = provided[name];\n    if (value !== undefined) secrets.push(value);\n  }\n  secrets.push(...environmentSecrets(source, passEnv));\n  const content = payload.cli.credential.content;\n  if (content !== null && typeof content === 'object')\n    for (const [key, value] of Object.entries(content))\n      if (typeof value === 'string' && CREDENTIAL_SECRET.test(key))\n        secrets.push(value);\n  if (connection !== undefined) secrets.push(connection.runnerKey);\n  return secrets;\n}\n\n/** Events sent as soon as they happen instead of at the spool's next interval. */\nconst IMMEDIATE_EVENTS: ReadonlySet<string> = new Set([\n  'toolUse',\n  'toolResult',\n  'input',\n  'status',\n  'usage',\n  'error',\n]);\n\n/** A redactor that takes in secrets the run is given later, such as a repository credential issued on demand. */\nexport class GrowingRedactor implements Redactor {\n  private current: Redactor;\n\n  constructor(initial: Redactor) {\n    this.current = initial;\n  }\n\n  get secrets(): readonly string[] {\n    return this.current.secrets;\n  }\n\n  add(secrets: Iterable<string | null | undefined>): void {\n    this.current = this.current.with(secrets);\n  }\n\n  text(text: string): string {\n    return this.current.text(text);\n  }\n\n  optional(text: string | undefined): string | undefined {\n    return this.current.optional(text);\n  }\n\n  value<T>(value: T): T {\n    return this.current.value(value);\n  }\n\n  with(secrets: Iterable<string | null | undefined>): Redactor {\n    return this.current.with(secrets);\n  }\n}\n\nfunction failureReason(result: AdapterResult): {\n  reason: FailureReason;\n  detail: string;\n} {\n  const error = result.error as\n    { reason?: unknown; message?: unknown } | undefined;\n  const parsed = FailureReasonSchema.safeParse(error?.reason);\n  const detail =\n    typeof error?.message === 'string' ? error.message : 'The tool failed.';\n  return {\n    reason: isDiskFull(result.error)\n      ? 'runnerDiskFull'\n      : parsed.success\n        ? parsed.data\n        : 'toolProcess',\n    detail,\n  };\n}\n\nexport class RunWorker {\n  private readonly payload: RunPayload;\n  private readonly timings: Timings;\n  private readonly deps: WorkerDeps;\n  private readonly client: ApiClient;\n  private readonly redactor: GrowingRedactor;\n  private readonly broker: GitCredentialBroker | undefined;\n  private credentialServer: CredentialServer | undefined;\n  /** Where the run's host tool wrappers are (host-tools.ts), removed when it ends. */\n  private hostToolsDir: string | undefined;\n  private readonly runId: string;\n  private readonly record: RunRecord;\n  private readonly spool: EventSpool;\n  private readonly output?: OutputWriter;\n  private readonly preview?: PreviewTransport;\n  private readonly lease: LeaseKeeper;\n  private readonly abort = new AbortController();\n  private readonly inputs = new Map<string, RunInput>();\n  /** Inputs that produced an `input` event: they reached the agent, and `complete` reports them as handled. */\n  private readonly delivered = new Set<string>();\n  /** Inputs handed to `steer()` in the current turn and not yet picked up by the agent. */\n  private readonly steered = new Set<string>();\n  private summaryText: string | undefined;\n  private readonly usage: Usage[] = [];\n  private ending: Ending | undefined;\n  private handle: AdapterHandle | undefined;\n  private statusTimer: NodeJS.Timeout | undefined;\n  private idleTimer: NodeJS.Timeout | undefined;\n  private lastActivity = Date.now();\n  private sessionId: string | undefined;\n  private confirmedSessionId: string | undefined;\n  private prepared: PrepareContext | undefined;\n  private readonly releases: (() => Promise<void>)[] = [];\n  private credentialsFile: string | undefined;\n  private runTemp: RunTemp | undefined;\n\n  constructor(\n    payload: RunPayload,\n    timings: Timings,\n    deps: WorkerDeps,\n    record: RunRecord,\n  ) {\n    this.payload = payload;\n    this.timings = timings;\n    this.redactor = new GrowingRedactor(\n      createRedactor(\n        runSecrets(\n          payload,\n          deps.connection,\n          process.env,\n          deps.settings.passEnv,\n        ),\n      ),\n    );\n    const redact = this.redactor;\n    this.deps = {\n      ...deps,\n      log: (message: string) => deps.log(redact.text(message)),\n    };\n    this.client = deps.client ?? runnerClient(deps.connection);\n    this.runId = payload.run.id;\n    this.record = record;\n    this.sessionId =\n      payload.prompt.session === 'resume'\n        ? payload.prompt.resumeSessionId\n        : undefined;\n    this.spool = EventSpool.open({\n      runsDir: deps.paths.runsDir,\n      runId: this.runId,\n      client: this.client,\n      firstSeq: payload.run.firstSeq,\n      flushIntervalMs: timings.eventFlushMs,\n      redactor: this.redactor,\n      log: this.deps.log,\n      onFatal: (error) => {\n        if (LOST_CODES.has(error.reason))\n          this.end({ kind: 'lost', code: error.reason });\n      },\n      onResponse: (body) => this.answered(body),\n    });\n    if (payload.outputBlocks === true) {\n      this.preview = new PreviewTransport(this.client, this.runId, (body) =>\n        this.answered(body),\n      );\n      this.output = new OutputWriter(\n        (event) => {\n          this.spool.push(event);\n        },\n        this.redactor,\n        payload.outputBlocks === true,\n        (event) => this.preview!.send(event),\n      );\n    }\n    this.lease = new LeaseKeeper({\n      client: this.client,\n      runId: this.runId,\n      intervalMs: timings.leaseIntervalMs,\n      log: this.deps.log,\n      onRenewed: (response) =>\n        this.absorb(response.cancelRequested, response.inputs),\n      onLost: (error) => this.end({ kind: 'lost', code: error.reason }),\n    });\n    const git = payload.workspace.git;\n    this.broker =\n      (git?.onDemand?.length ?? 0) > 0 || (git?.credentials?.length ?? 0) > 0\n        ? new GitCredentialBroker({\n            client: this.client,\n            runId: this.runId,\n            attempt: payload.run.attempt,\n            ...(git?.onDemand ? { onDemand: git.onDemand } : {}),\n            ...(git?.credentials ? { credentials: git.credentials } : {}),\n            onSecret: (secret) => this.redactor.add([secret]),\n            onLost: (code) => this.end({ kind: 'lost', code }),\n            event: (event) => this.writeEvent(event),\n            log: this.deps.log,\n          })\n        : undefined;\n    for (const input of payload.inputs) this.inputs.set(input.id, input);\n  }\n\n  /** Asks the run to end; the first reason wins. */\n  end(ending: Ending): void {\n    if (this.ending !== undefined) return;\n    this.ending = ending;\n    this.deps.log(`run ${this.runId}: ending (${ending.kind})`);\n    this.abort.abort();\n  }\n\n  /** Polls status now; the daemon sends SIGUSR2 when its heartbeat learns of a cancel. */\n  async pollStatus(): Promise<void> {\n    try {\n      const status = await this.client.get(\n        routePath(RUNNER_ROUTES.status, { runId: this.runId }),\n        StatusResponseSchema,\n        { timeoutMs: 10_000 },\n      );\n      if (\n        status.status === 'cancelled' ||\n        status.status === 'failed' ||\n        status.status === 'completed'\n      ) {\n        this.end({ kind: 'lost', code: 'RUN_NOT_ACTIVE' });\n        return;\n      }\n      this.absorb(status.cancelRequested, status.inputs);\n    } catch (error) {\n      if (error instanceof ApiError && LOST_CODES.has(error.reason))\n        this.end({ kind: 'lost', code: error.reason });\n    }\n  }\n\n  /** An events answer: input sent while the agent works arrives with it, without waiting for the next poll. */\n  private answered(body: unknown): void {\n    const response = EventsResponseSchema.safeParse(dataOf(body));\n    if (response.success && response.data.inputs?.length)\n      this.absorb(response.data.cancelRequested, response.data.inputs);\n  }\n\n  private absorb(cancelRequested: boolean, inputs: readonly RunInput[]): void {\n    if (cancelRequested) {\n      this.end({ kind: 'cancel' });\n      return;\n    }\n    for (const input of inputs) {\n      if (this.inputs.has(input.id)) continue;\n      this.inputs.set(input.id, input);\n      void this.steer(input);\n    }\n  }\n\n  /**\n   * Hands an input to the running turn. The adapter emits an `input` event once the agent picks it up (see\n   * `recordEvent`); an input still waiting when the turn ends goes into the next turn's prompt.\n   */\n  private async steer(input: RunInput): Promise<void> {\n    const handle = this.handle;\n    if (handle === undefined || this.ending !== undefined) return;\n    if (this.delivered.has(input.id) || this.steered.has(input.id)) return;\n    this.steered.add(input.id);\n    const accepted = await handle\n      .steer(formatInputs([input]), input.id)\n      .catch(() => false);\n    if (!accepted) this.steered.delete(input.id);\n  }\n\n  /** Puts inputs into a prompt the runner composes, recording each as delivered. */\n  private deliverInPrompt(\n    inputs: readonly RunInput[],\n    mode: 'prompt' | 'turn',\n  ): void {\n    for (const input of inputs) {\n      this.delivered.add(input.id);\n      this.writeEvent({\n        type: 'input',\n        content: input.text,\n        meta: { inputId: input.id, mode },\n      });\n    }\n  }\n\n  /** Spools an adapter event, noting the inputs it reports as picked up. */\n  private quota: QuotaReport | undefined;\n  private recordEvent(event: AdapterEvent): void {\n    const quota = QuotaReportSchema.safeParse(event.meta?.quota);\n    if (quota.success) {\n      const windows = new Map(\n        (this.quota?.windows ?? []).map((window) => [\n          JSON.stringify([window.scope, window.target, window.window]),\n          window,\n        ]),\n      );\n      for (const window of quota.data.windows)\n        if (window.exhausted)\n          windows.set(\n            JSON.stringify([window.scope, window.target, window.window]),\n            window,\n          );\n      if (windows.size) this.quota = { windows: [...windows.values()] };\n    }\n    if (event.type === 'status' && event.content === 'sessionRecovery') {\n      this.sessionId = undefined;\n      this.confirmedSessionId = undefined;\n    }\n    if (\n      event.type === 'status' &&\n      event.content === 'started' &&\n      typeof event.meta?.sessionId === 'string'\n    ) {\n      this.sessionId = event.meta.sessionId;\n      this.confirmedSessionId = event.meta.sessionId;\n    }\n    if (event.type === 'input') {\n      const inputId = event.meta?.inputId;\n      if (typeof inputId === 'string' && this.inputs.has(inputId)) {\n        this.delivered.add(inputId);\n        this.steered.delete(inputId);\n      }\n    }\n    this.writeEvent(event);\n  }\n\n  private writeEvent(event: Parameters<EventSpool['push']>[0]): void {\n    if (this.output) this.output.write(event);\n    else this.spool.push(event);\n    // A conversation shows each step, the input the agent took and the turn's end as they happen: send them now\n    // rather than at the next interval. Text keeps the interval (or its own previews).\n    if (IMMEDIATE_EVENTS.has(event.type))\n      void this.spool.flush().catch(() => undefined);\n  }\n\n  private undelivered(): RunInput[] {\n    return [...this.inputs.values()].filter(\n      (input) => !this.delivered.has(input.id) && !this.steered.has(input.id),\n    );\n  }\n\n  private async updateRecord(patch: Partial<RunRecord>): Promise<void> {\n    Object.assign(this.record, patch);\n    await writeRecord(this.deps.paths, this.record);\n  }\n\n  /** POSTs a final report, retrying transient failures. False when the run is no longer this runner's. */\n  private async report(route: string, body: unknown): Promise<boolean> {\n    const deadline = Date.now() + (this.timings.reportTimeoutMs ?? 10 * 60_000);\n    for (let attemp