ng;\n\n  private retainWorkspace = false;\n\n  private async saveLocal(\n    remove = false,\n    bestEffortEvents = false,\n  ): Promise<string> {\n    await this.stopTool();\n    if (this.writerStopFailure === undefined) {\n      try {\n        await this.deps.stopWriters?.();\n      } catch (error) {\n        this.writerStopFailure = `Process stop failed: ${String(error)}`;\n      }\n    }\n    const workDir = this.prepared?.workspace?.workDir;\n    if (workDir === undefined) return '';\n    // Stopping this run never commits, pushes or removes shared code.\n    void remove;\n    void bestEffortEvents;\n    if (this.writerStopFailure !== undefined) {\n      const meta = await readWorkspaceMeta(this.deps.paths, workDir);\n      if (meta)\n        await writeWorkspaceMeta(this.deps.paths, workDir, {\n          ...meta,\n          recoveryRequired: true,\n          recoveryReason: this.writerStopFailure,\n        });\n    }\n    return this.writerStopFailure === undefined\n      ? ''\n      : `Directory retained: ${workDir}: ${this.writerStopFailure}`;\n  }\n\n  private async finishCompleted(): Promise<WorkerOutcome | 'inputPending'> {\n    await this.updateRecord({ phase: 'reporting' });\n    await this.stopTool();\n    await this.deps.stopWriters?.().catch((error: unknown) => {\n      // A read-only run keeps its checkout for GC; a writer pushes nothing past a writer it could not stop.\n      if (this.payload.workspace.readOnly !== true) throw error;\n      this.writerStopFailure = `Process stop failed: ${String(error)}`;\n    });\n    const repos = await this.repoReports(false);\n    const workDir = this.prepared?.workspace?.workDir;\n    const saved = await this.saveLocal();\n    await this.drainEvents();\n    if (this.ending !== undefined) return this.finishEnding();\n    try {\n      await this.report(\n        routePath(RUNNER_ROUTES.complete, { runId: this.runId }),\n        {\n          summary:\n            saved === '' ? this.summary() : `${this.summary()}\\n\\n${saved}`,\n          handledInputIds: [...this.delivered],\n          usage: this.usage,\n          ...(this.sessionId === undefined\n            ? {}\n            : { sessionId: this.sessionId }),\n          repos,\n        },\n      );\n    } catch (error) {\n      if (error instanceof ApiError && error.reason === 'RUN_INPUT_PENDING')\n        return 'inputPending';\n      if (\n        error instanceof ApiError &&\n        error.reason === 'RUN_CANCEL_REQUESTED'\n      ) {\n        this.end({ kind: 'cancel' });\n        return this.finishEnding();\n      }\n      if (error instanceof ApiError && LOST_CODES.has(error.reason)) {\n        this.end({ kind: 'lost', code: error.reason });\n        return 'leaseLost';\n      }\n      throw error;\n    }\n    if (workDir !== undefined)\n      await markDirsPrepared(\n        this.deps.paths,\n        workDir,\n        this.prepared?.dirs ?? [],\n      );\n    this.deps.log(`run ${this.runId}: completed`);\n    return 'completed';\n  }\n\n  private summary(): string {\n    // Without a summary from the tool, the last text it wrote (redacted as it was spooled) is the closest thing to one.\n    return this.summaryText === undefined\n      ? (this.spool.lastText ?? 'Run completed.')\n      : this.redactor.text(this.summaryText);\n  }\n\n  private async finishFailed(\n    reason: FailureReason,\n    unredacted: string,\n    remove = false,\n  ): Promise<WorkerOutcome> {\n    const detail = this.redactor.text(unredacted);\n    await this.updateRecord({ phase: 'reporting' }).catch(() => undefined);\n    const repos = await this.repoReports(false).catch(() => []);\n    let saved: string;\n    if (reason === 'runnerDiskFull') {\n      this.spool.stop();\n      try {\n        saved = await this.saveLocal(false, true);\n      } catch (error) {\n        this.retainWorkspace = true;\n        saved = `Local preservation did not finish; workspace retained for recovery: ${this.redactor.text(String(error))}`;\n        this.deps.log(`run ${this.runId}: ${saved}`);\n      }\n      // A full disk may also prevent writing the event acknowledgement. The final failure still must reach the server.\n      await this.drainEvents().catch((error: unknown) =>\n        this.deps.log(\n          `run ${this.runId}: event drain failed while reporting disk exhaustion: ${this.redactor.text(error instanceof Error ? error.message : String(error))}`,\n        ),\n      );\n    } else {\n      saved = await this.saveLocal(remove);\n      await this.drainEvents();\n    }\n\n    try {\n      await this.report(routePath(RUNNER_ROUTES.fail, { runId: this.runId }), {\n        reason,\n        ...(reason === 'toolQuota' && this.quota ? { quota: this.quota } : {}),\n        detail: saved === '' ? detail : `${detail}\\n\\n${saved}`,\n        handledInputIds: [...this.delivered],\n        usage: this.usage,\n        ...(this.sessionId === undefined ? {} : { sessionId: this.sessionId }),\n        repos,\n      });\n    } catch (error) {\n      if (error instanceof ApiError && LOST_CODES.has(error.reason))\n        return 'leaseLost';\n      throw error;\n    }\n    this.deps.log(`run ${this.runId}: failed (${reason}): ${detail}`);\n    return 'failed';\n  }\n\n  private async finishEnding(): Promise<WorkerOutcome> {\n    const ending = this.ending;\n    await this.stopTool();\n    if (ending?.kind === 'lost') await this.saveLocal(true);\n    switch (ending?.kind) {\n      case 'lost':\n        this.deps.log(\n          `run ${this.runId}: lease lost (${ending.code}); tool stopped`,\n        );\n        return 'leaseLost';\n      case 'cancel': {\n        const saved = await this.saveLocal(true);\n        this.writeEvent({\n          type: 'status',\n          content: saved.includes('Recovery required:')\n            ? `Cancelled. ${saved}`\n            : 'Cancelled.',\n          meta: { status: 'cancelled' },\n        });\n        await this.drainEvents();\n        try {\n          await this.report(\n            routePath(RUNNER_ROUTES.cancelAck, { runId: this.runId }),\n            {\n              ...(this.confirmedSessionId === undefined\n                ? {}\n                : { sessionId: this.confirmedSessionId }),\n              handledInputIds: [...this.delivered],\n              usage: this.usage,\n            },\n          );\n        } catch (error) {\n          if (!(error instanceof ApiError && LOST_CODES.has(error.reason)))\n            throw error;\n        }\n        this.deps.log(`run ${this.runId}: cancelled`);\n        return 'cancelled';\n      }\n      case 'upgrade': {\n        await this.finishFailed(\n          'runnerUpgrade',\n          'The runner interrupted this attempt to install an update.',\n          true,\n        );\n        return 'stopped';\n      }\n      case 'shutdown':\n        await this.finishFailed(\n          'runnerOffline',\n          'The runner stopped while the run was in progress.',\n        );\n        return 'stopped';\n      case 'idle':\n        return this.finishFailed(\n          'idleTimeout',\n          `No activity from the tool for ${this.payload.tool.policy.idleTimeoutMs} ms.`,\n        );\n      default:\n        return this.finishFailed(\n          'unknown',\n          'The run ended for no recorded reason.',\n        );\n    }\n  }\n}\n"
    },
    {
      "path": "packages/plugins/app-plugin-agents/server/routes/runners/runner.ts",
      "content": "import { takeToolDetection } from '../../runners/tool-detection.js';\n/**\n * The runner endpoints (`RUNNER_ROUTES` of `@nocobase/agent-protocol`), mounted at `/api/agents/runners` beside the\n * people's runners API (`admin.ts`), so every route names its own authentication: every path but `register` the\n * runner's key header, never the browser session. A `GET` checks the key without marking the runner seen. Every\n * answer is `{ data }`.\n *\n * One long-poll claim hands out jobs and agent runs from the runner's shared slots: jobs first (they are short and\n * people wait on them), then runs. The heartbeat reconciles both, and a run's own `runs/:runId/*` endpoints\n * (`runs.ts`) are mounted here, behind the same key.\n *\n * A runner speaking a protocol this application does not serve (its `HEADERS.protocol`, or the one it registered with)\n * is kept connected rather than refused: `register` registers it, `heartbeat` reads what it can of the report and\n * answers with `compatibility` (and an `upgrade` notice when a newer runner is served), releasing whatever it holds,\n * and `claim` answers no work. Run and job reports from it are refused with `PROTOCOL_UNSUPPORTED`; the sweeper takes\n * its work back. Its fields this application does not know (features, tools) are dropped rather than refused.\n */\nimport {\n  ClaimRequestSchema,\n  ClaimResponseSchema,\n  EventsResponseSchema,\n  HEADERS,\n  HeartbeatRequestSchema,\n  HeartbeatResponseSchema,\n  JobFinishResponseSchema,\n  JobLeaseResponseSchema,\n  JobStatusResponseSchema,\n  JobCancelAckRequestSchema,\n  JobCompleteRequestSchema,\n  JobEventsRequestSchema,\n  JobFailRequestSchema,\n  JobStartRequestSchema,\n  ActiveJobSchema,\n  ActiveRunSchema,\n  isProtocolSupported,\n  LeaseRequestSchema,\n  MIN_PROTOCOL_VERSION,\n  PROTOCOL_VERSION,\n  ProtocolError,\n  RegisterRequestSchema,\n  RegisterResponseSchema,\n  RunnerFeatureSchema,\n  RunnerPolicySchema,\n  TIMINGS,\n  ReportedToolInfoSchema,\n  WorkspacesRequestSchema,\n  WorkspacesResponseSchema,\n  type ClaimRequest,\n  type ClaimResponse,\n  type HeartbeatRequest,\n  type HeartbeatResponse,\n  type RegisterRequest,\n} from '@nocobase/agent-protocol';\nimport {\n  apiErrorResponse,\n  apiValidator,\n  dataResponse,\n  cliRoute,\n  describeRoute,\n  parseApiInput,\n} from '@nocobase/app-server/router';\nimport type { Context, Hono, MiddlewareHandler } from 'hono';\nimport { z } from 'zod';\n\nimport type { Runner } from '../../../shared/runners.js';\nimport type { Agents } from '../../composition.js';\nimport { createClaimScan, type ClaimScan } from '../../core/runs/claim.js';\nimport { upgradeFields, upgradeFor } from '../../distribution/index.js';\nimport { pause } from '../../kernel/clock.js';\nimport { domainRouter } from '../../kernel/http.js';\nimport { upgradeRequiredOf, type RunnerEnv } from '../../runners/index.js';\nimport { ClaimQuery, JobParams } from '../schemas.js';\nimport {\n  heldWorkErrors,\n  jsonRequestBody,\n  protocolHeader,\n  runnerKeyErrors,\n  runnerKeySecurity,\n  tags,\n} from '../openapi.js';\nimport { mountRunnerRunRoutes } from './runs.js';\n\nexport interface RunnerRoutesOptions {\n  /** How long a `claim?wait=true` is held without work; `TIMINGS.pollTimeoutMs` by default. */\n  readonly pollTimeoutMs?: number;\n}\n\nfunction runnerKey(context: Context): string {\n  return context.req.header(HEADERS.runnerKey) ?? '';\n}\n\n/** The protocol the request says it speaks; undefined when it says none (a runner from before the header). */\nfunction protocolOf(context: Context): number | undefined {\n  const header = context.req.header(HEADERS.protocol);\n  if (header === undefined || header.trim() === '') return undefined;\n  const version = Number(header);\n  return Number.isInteger(version) ? version : 0;\n}\n\nfunction unsupported(protocolVersion: number): ProtocolError {\n  return new ProtocolError(\n    'PROTOCOL_UNSUPPORTED',\n    upgradeRequiredOf(protocolVersion).message,\n    {\n      protocolVersion: PROTOCOL_VERSION,\n      minProtocolVersion: MIN_PROTOCOL_VERSION,\n    },\n  );\n}\n\nconst isRecord = (value: unknown): value is Record<string, unknown> =>\n  typeof value === 'object' && value !== null && !Array.isArray(value);\n\n/** The entries of `value` that `schema` reads. */\nfunction known<T>(value: unknown, schema: z.ZodType<T>): T[] {\n  if (!Array.isArray(value)) return [];\n  return value.flatMap((item) => {\n    const parsed = schema.safeParse(item);\n    return parsed.success ? [parsed.data] : [];\n  });\n}\n\n/**\n * A registration from a runner of a protocol this application does not serve: its features and tools are read as far\n * as this application knows them, so it can still register and be shown as needing an upgrade.\n */\nconst LenientRegisterSchema: z.ZodType<RegisterRequest> = z.preprocess(\n  (raw) =>\n    isRecord(raw) &&\n    typeof raw.protocolVersion === 'number' &&\n    !isProtocolSupported(raw.protocolVersion)\n      ? {\n          ...raw,\n          features: known(raw.features, RunnerFeatureSchema),\n          tools: known(raw.tools, ReportedToolInfoSchema),\n        }\n      : raw,\n  RegisterRequestSchema,\n);\n\n/** A heartbeat from a runner that needs an upgrade: whatever of it this application can read. */\nconst LenientHeartbeatSchema: z.ZodType<HeartbeatRequest> = z.preprocess(\n  (raw) => {\n    const body = isRecord(raw) ? raw : {};\n    const load = isRecord(body.load) ? body.load : {};\n    const count = (value: unknown) =>\n      typeof value === 'number' && Number.isInteger(value) && value >= 0\n        ? value\n        : 0;\n    return {\n      version:\n        typeof body.version === 'string' ? body.version.slice(0, 64) : '',\n      features: known(body.features, RunnerFeatureSchema),\n      tools: known(body.tools, ReportedToolInfoSchema),\n      active: known(body.active, ActiveRunSchema),\n      ...(Array.isArray(body.jobs)\n        ? { jobs: known(body.jobs, ActiveJobSchema) }\n        : {}),\n      load: { slots: count(load.slots), free: count(load.free) },\n      ...(RunnerPolicySchema.safeParse(body.policy).success\n        ? { policy: RunnerPolicySchema.parse(body.policy) }\n        : {}),\n    };\n  },\n  HeartbeatRequestSchema,\n);\n\nexport function createRunnerRoutes(\n  services: Agents,\n  options: RunnerRoutesOptions = {},\n): Hono<RunnerEnv> {\n  const pollTimeoutMs = options.pollTimeoutMs ?? TIMINGS.pollTimeoutMs;\n  const router = domainRouter<RunnerEnv>();\n\n  const authenticate = (context: Context<RunnerEnv>, touch: boolean) => {\n    const protocolVersion = protocolOf(context);\n    return services.runners.authenticate(runnerKey(context), {\n      ...(protocolVersion === undefined ? {} : { protocolVersion }),\n      touch,\n    });\n  };\n  const authenticated: MiddlewareHandler<RunnerEnv> = async (context, next) => {\n    context.set(\n      'runner',\n      await authenticate(context, context.req.method !== 'GET'),\n    );\n    await next();\n  };\n  // Reports on runs and jobs need a runner this application can work with.\n  const served: MiddlewareHandler<RunnerEnv> = async (context, next) => {\n    const runner = context.get('runner');\n    if (runner.status === 'upgrade_required')\n      throw unsupported(runner.protocolVersion);\n    await next();\n  };\n\n  router.post(\n    '/register',\n    describeRoute({\n      tags,\n      summary: 'Register a runner',\n      operationId: 'agentsRunnerRegister',\n      // Runner protocol: only a runner calls it.\n      ...cliRoute(false),\n      description:\n        'Registers the host as a runner with the one-time registration token in the body (no other credential), and answers the runner key every later runner request sends in `x-nocobase-runner-key`. A runner of a protocol this application does not serve still registers, and is shown as needing an upgrade.',\n      security: [],\n      parameters: [protocolHeader],\n      responses: {\n        200: dataResponse(RegisterResponseSchema),\n        401: apiErrorResponse(\n          401,\n          'The registration token is unknown, used or expired (`REGISTRATION_TOKEN_INVALID`).',\n        ),\n        500: apiErrorResponse(500),\n      },\n    }),\n    apiValidator('json', LenientRegisterSchema),\n    async (context) =>\n      context.json({\n        data: await services.runners.register(context.req.valid('json')),\n      }),\n  );\n\n  router.post(\n    '/heartbeat',\n    authenticated,\n    describeRoute({\n      tags,\n      summary: 'Send a runner heartbeat',\n      operationId: 'agentsRunnerHeartbeat',\n      // Runner protocol: only a runner calls it.\n      ...cliRoute(false),\n      description:\n        \"Reports what the runner holds and its load, every `heartbeatIntervalMs`, and answers which runs and jobs to cancel or release, and whether an upgrade is available: a tarball in `upgrade`, or, only to a runner with the `npm` feature when the application has no tarball of its product, a package to install from npm in `npmUpgrade`. A runner of a protocol this application does not serve is answered with `compatibility` and told to release everything it holds. The body is validated in the handler, against what the runner's protocol allows.\",\n      security: runnerKeySecurity,\n      parameters: [protocolHeader],\n      requestBody: jsonRequestBody(HeartbeatRequestSchema),\n      responses: {\n        200: dataResponse(HeartbeatResponseSchema),\n        400: apiErrorResponse(\n          400,\n          'The body is not a heartbeat (`INVALID_ARGUMENT`).',\n        ),\n        ...runnerKeyErrors,\n      },\n    }),\n    async (context) => {\n      const current = context.get('runner');\n      if (current.status === 'upgrade_required') {\n        const request = parseApiInput(\n          LenientHeartbeatSchema,\n          await jsonOf(context),\n        );\n        const runner = await services.runners.heartbeat(current, request);\n        const upgrade = await upgradeFor(services.dist, runner);\n        // It holds nothing this application can let it finish: the sweeper gives its runs and jobs back to the queue.\n        const response: HeartbeatResponse = {\n          ok: true,\n          serverTime: services.clock.now().toISOString(),\n          protocolVersion: PROTOCOL_VERSION,\n          capacity: { slots: runner.slots, toolSlots: runner.toolSlots ?? {} },\n          ...upgradeFields(upgrade),\n          compatibility: upgradeRequiredOf(runner.protocolVersion),\n          cancelRequested: [],\n          release: request.active.map((run) => run.runId),\n          ...(request.jobs\n            ? {\n                jobs: {\n                  cancelRequested: [],\n                  release: request.jobs.map((job) => job.jobId),\n                },\n              }\n            : {}),\n        };\n        return context.json({ data: response });\n      }\n      const request = parseApiInput(\n        HeartbeatRequestSchema,\n        await jsonOf(context),\n      );\n      const runner = await services.runners.heartbeat(current, request);\n      const { cancelRequested, release } = await services.reports.reconcile(\n        runner,\n        request.active,\n      );\n      const jobs = request.jobs\n        ? await services.jobs.runner.reconcile(runner, request.jobs)\n        : undefined;\n      const upgrade = await upgradeFor(services.dist, runner);\n      const response: HeartbeatResponse = {\n        ok: true,\n        serverTime: services.clock.now().toISOString(),\n        protocolVersion: PROTOCOL_VERSION,\n        enabledTools: runner.enabledTools ?? [],\n        detectTools: takeToolDetection(runner.id),\n        capacity: { slots: runner.slots, toolSlots: runner.toolSlots ?? {} },\n        ...upgradeFields(upgrade),\n        cancelRequested,\n        release,\n        ...(jobs ? { jobs } : {}),\n        workspaces: services.workspaces.reporting,\n      };\n      return context.json({ data: response });\n    },\n  );\n\n  router.post(\n    '/workspaces',\n    authenticated,\n    served,\n    describeRoute({\n      tags,\n      summary: \"Report a runner's working directories\",\n      operationId: 'agentsRunnerReportWorkspaces',\n      // Runner protocol: only a runner calls it.\n      ...cliRoute(false),\n      description:\n        'Reports the working directories the runner keeps for this application, each with the last run that worked in it, its size and whether it holds unpushed work, and answers which of those runs belong to subjects whose work is over (`remove`: their directories may go) or goes on (`keep`). Runs of other runners, unknown runs, and subjects whose binding cannot say are in neither list. The report is kept for the runtimes pages. A runner sends it only when the heartbeat answer carries `workspaces`.',\n      security: runnerKeySecurity,\n      parameters: [protocolHeader],\n      responses: {\n        200: dataResponse(WorkspacesResponseSchema),\n        400: apiErrorResponse(\n          400,\n          'The runner speaks a protocol this application does not serve (`PROTOCOL_UNSUPPORTED`).',\n        ),\n        ...runnerKeyErrors,\n      },\n    }),\n    apiValidator('json', WorkspacesRequestSchema),\n    async (context) =>\n      context.json({\n        data: await services.workspaces.report(\n          context.get('runner'),\n          context.req.valid('json'),\n        ),\n      }),\n  );\n\n  // Runs and jobs share the runner's slots: jobs first (they are short and people wait on them), then runs. Jobs run\n  // no coding tool, so only runs are bounded by the runner's room per tool. One run per request: the runner asks\n  // again at once, and each claim waits by how busy the runner already is with the run's tool, so idler runners\n  // take the next run first (`ClaimService.claim`). A request that goes away while it waits takes nothing. A request\n  // that took jobs takes no run, so its jobs are not held by a run's wait: the runner asks again at once for the run.\n  const claimWork = async (\n    runner: Runner,\n    request: ClaimRequest,\n    scan: ClaimScan,\n    signal: AbortSignal,\n  ) => {\n    const { free } = request;\n    const jobs = await services.jobs.runner.claim(runner, free);\n    const runs =\n      jobs.length === 0 && free > 0\n        ? await services.claims.claim(runner, 1, request.tools, scan, signal)\n        : [];\n    return { runs, jobs };\n  };\n  router.post(\n    '/claim',\n    authenticated,\n    describeRoute({\n      tags,\n      summary: 'Claim work for a runner',\n      operationId: 'agentsRunnerClaimWork',\n      // Runner protocol: only a runner calls it.\n      ...cliRoute(false),\n      description: [\n        \"Hands the runner work for its free slots: jobs first, up to `free`, or, when there is no job to hand out, at most one agent run. A run is handed out after a wait of up to one second after it entered the queue, longer the more of the run's coding tool the runner already holds against its limit for that tool, so the idlest runners take queued runs first; the runner asks again at once for the next. A request that ends while it waits takes nothing. With `wait=true` and nothing to hand out, the request is held as a long poll for up to `pollTimeoutMs` (25 seconds by default) until work arrives, and then answers what it found, possibly nothing; the runner asks again at once. Without `wait`, it answers immediately.\",\n        '',\n        'A runner of a protocol this application does not serve is given no work (its poll is still held). `jobs` is present only when jobs are handed out.',\n      ].join('\\n'),\n      security: runnerKeySecurity,\n      parameters: [protocolHeader],\n      requestBody: jsonRequestBody(ClaimRequestSchema),\n      responses: {\n        200: dataResponse(ClaimResponseSchema),\n        400: apiErrorResponse(\n          400,\n          'The body is not a claim (`INVALID_ARGUMENT`).',\n        ),\n        ...runnerKeyErrors,\n      },\n    }),\n    apiValidator('query', ClaimQuery),\n    async (context) => {\n      const runner = context.get('runner');\n      const wait = context.req.valid('query').wait === true;\n      if (runner.status === 'upgrade_required') {\n        // No work until it is upgraded; hold the poll as for an empty queue, so it does not ask again at once.\n        if (wait) await pause(pollTimeoutMs, context.req.raw.signal);\n        return context.json({ data: { runs: [] } satisfies ClaimResponse });\n      }\n      const request = parseApiInput(ClaimRequestSchema, await jsonOf(context));\n      const { free } = request;\n      const scan = createClaimScan();\n      const { signal } = context.req.raw;\n      let work = await claimWork(runner, request, scan, signal);\n      if (\n        work.runs.length === 0 &&\n        work.jobs.length === 0 &&\n        free > 0 &&\n        wait\n      ) {\n        const outcome = await services.signal.wait(pollTimeoutMs, signal);\n        if (outcome !== 'aborted')\n          // The runner may have been revoked while it waited.\n          work = await claimWork(\n            await authenticate(context, true),\n            request,\n            scan,\n            signal,\n          );\n      }\n      // A runner of protocol 3 is never handed a job (it announces no job feature), so `jobs` stays out of its answer.\n      const response: ClaimResponse =\n        work.jobs.length > 0 ? work : { runs: work.runs };\n      return context.json({ data: response });\n    },\n  );\n\n  // A run's own endpoints: its lease, reports, skills and mounts.\n  router.use('/runs/*', authenticated, served);\n  const runs = domainRouter<RunnerEnv>();\n  mountRunnerRunRoutes(runs, services);\n  router.route('/runs', runs);\n\n  // Jobs (protocol 4): the same reports as a run's, on the job.\n  router.use('/jobs/*', authenticated, served);\n  const job = (\n    operationId: string,\n    summary: string,\n    response: z.ZodType,\n    description?: string,\n  ) =>\n    describeRoute({\n      tags,\n      summary,\n      operationId,\n      // Runner protocol: only a runner calls it.\n      ...cliRoute(false),\n      ...(description ? { description } : {}),\n      security: runnerKeySecurity,\n      parameters: [protocolHeader],\n      responses: { 200: dataResponse(response), ...heldWorkErrors },\n    });\n  router.post(\n    '/jobs/:jobId/lease',\n    job(\n      'agentsRunnerRenewJobLease',\n      \"Renew a job's lease\",\n      JobLeaseResponseSchema,\n    ),\n    apiValidator('param', JobParams),\n    apiValidator('json', LeaseRequestSchema),\n    async (context) =>\n      context.json({\n        data: await services.jobs.runner.lease(\n          context.get('runner'),\n          context.req.valid('param').jobId,\n        ),\n      }),\n  );\n  router.post(\n    '/jobs/:jobId/start',\n    job(\n      'agentsRunnerStartJob',\n      'Report that a job started',\n      JobLeaseResponseSchema,\n    ),\n    apiValidator('param', JobParams),\n    apiValidator('json', JobStartRequestSchema),\n    async (context) =>\n      context.json({\n        data: await services.jobs.runner.start(\n          context.get('runner'),\n          context.req.valid('param').jobId,\n          context.req.valid('json'),\n        ),\n      }),\n  );\n  router.post(\n    '/jobs/:jobId/events',\n    job(\n      'agentsRunnerReportJobEvents',\n      \"Report a job's events\",\n      EventsResponseSchema,\n    ),\n    apiValidator('param', JobParams),\n    apiValidator('json', JobEventsRequestSchema),\n    async (context) =>\n      context.json({\n        data: await services.jobs.runner.events(\n          context.get('runner'),\n          context.req.valid('param').jobId,\n          context.req.valid('json'),\n        ),\n      }),\n  );\n  router.get(\n    '/jobs/:jobId/status',\n    job(\n      'agentsRunnerGetJobStatus',\n      \"Get a job's status\",\n      JobStatusResponseSchema,\n      'Whether the job should go on or stop (a cancellation was asked for). Reading it does not count as the runner being seen.',\n    ),\n    apiValidator('param', JobParams),\n    async (context) =>\n      context.json({\n        data: await services.jobs.runner.status(\n          context.get('runner'),\n          context.req.valid('param').jobId,\n        ),\n      }),\n  );\n  router.post(\n    '/jobs/:jobId/complete',\n    job('agentsRunnerCompleteJob', 'Complete a job', JobFinishResponseSchema),\n    apiValidator('param', JobParams),\n    apiValidator('json', JobCompleteRequestSchema),\n    async (context) =>\n      context.json({\n        data: await services.jobs.runner.complete(\n          context.get('runner'),\n          context.req.valid('param').jobId,\n          context.req.valid('json'),\n        ),\n      }),\n  );\n  router.post(\n    '/jobs/:jobId/fail',\n    job('agentsRunnerFailJob', 'Fail a job', JobFinishResponseSchema),\n    apiValidator('param', JobParams),\n    apiValidator('json', JobFailRequestSchema),\n    async (context) =>\n      context.json({\n        data: await services.jobs.runner.fail(\n          context.get('runner'),\n          context.req.valid('param').jobId,\n          context.req.valid('json'),\n        ),\n      }),\n  );\n  router.post(\n    '/jobs/:jobId/cancelAck',\n    job(\n      'agentsRunnerAcknowledgeJobCancel',\n      \"Acknowledge a job's cancellation\",\n      JobFinishResponseSchema,\n    ),\n    apiValidator('param', JobParams),\n    apiValidator('json', JobCancelAckRequestSchema),\n    async (context) =>\n      context.json({\n        data: await services.jobs.runner.cancelAck(\n          context.get('runner'),\n          context.req.valid('param').jobId,\n        ),\n      }),\n  );\n\n  return router;\n}\n\n/** The JSON body of a request whose schema depends on the runner's state; `{}` when empty. */\nasync function jsonOf(context: Context): Promise<unknown> {\n  const text = await context.req.text();\n  if (text === '') return {};\n  try {\n    return JSON.parse(text) as unknown;\n  } catch {\n    throw new ProtocolError('INVALID_REQUEST', 'The body must be JSON.');\n  }\n}\n"
    },
    {
      "path": "packages/plugins/app-plugin-agents/shared/runners.ts",
      "content": "/**\n * Runners as the browser and the server's admin API exchange them.\n */\nimport type { QuotaLocation } from './quota.js';\n\nimport {\n  AGENT_TOOLS,\n  NATIVE_AGENT_TOOLS,\n  isNativeTool,\n  policyAllowsAgent,\n  type AgentTool,\n  type RunnerFeature,\n  type RunnerPolicy,\n  type RunStatus,\n  type ToolInfo,\n  type ToolLoad,\n  type ToolSlots,\n  type WorkspaceDecision,\n  type WorkspaceCleanupResult,\n} from '@nocobase/agent-protocol';\n\nimport { effortsFor, type RunnerModelEntry } from './agents.js';\nimport { normalizeModel } from './model-catalog.js';\n\n/**\n * `team` (shown as \"shared\") runs anyone's work; `ownerOnly` (shown as \"personal\") runs only work its owner started. A runner added by its\n * owner starts personal; the owner may share it with all users, and an administrator may add one shared from the start.\n */\nexport const RUNNER_TRUST = ['team', 'ownerOnly'] as const;\n\nexport type RunnerTrust = (typeof RUNNER_TRUST)[number];\n\n/**\n * `upgrade_required`: the runner is connected, but speaks a protocol this application does not serve\n * (`protocolVersion` outside `RunnerSummary.requiredProtocol`). It keeps sending heartbeats and is given no work until\n * it is upgraded; its owner is told once (the `notice` event).\n */\nexport const RUNNER_STATUSES = [\n  'online',\n  'offline',\n  'revoked',\n  'upgrade_required',\n] as const;\n\nexport type RunnerStatus = (typeof RUNNER_STATUSES)[number];\n\n/**\n * Optional payload support is established by capabilities, never package versions.\n * Protocol 9 runners may ignore workspace.key; only its explicit declaration is evidence.\n */\nexport function supportsWorkspaceKey(\n  runner: Pick<Runner, 'features'>,\n): boolean {\n  return runner.features.includes('workspaceKey');\n}\n\nexport interface Runner {\n  readonly id: string;\n  readonly name: string;\n  readonly hostname: string;\n  readonly os: string;\n  readonly arch: string;\n  readonly version: string;\n  /**\n   * The product it runs as and updates itself to, `nocobase-runner`; null for a runner that did not report one, which\n   * is offered no update.\n   */\n  readonly product: string | null;\n  readonly protocolVersion: number;\n  readonly features: readonly RunnerFeature[];\n  /** What the runner reported: version, sign-in and optional advisory model capabilities. Never edits Agent configuration. */\n  readonly tools: readonly ToolInfo[];\n  /**\n   * The coding tools people let this runner run, chosen on the web; null offers every tool it reports. A tool left\n   * out is still reported (with its version and sign-in) but never dispatched here.\n   */\n  readonly enabledTools: readonly AgentTool[] | null;\n  readonly trust: RunnerTrust;\n  readonly ownerUserId: string | null;\n  readonly ownerName: string | null;\n  readonly status: RunnerStatus;\n  /** Its slots, shared by runs and jobs. */\n  readonly slots: number;\n  /**\n   * How many runs of each coding tool it may hold at once, beside `slots` (`{ claude: 2, codex: 1 }`); a tool left\n   * out, or every tool when null or absent, is bounded by `slots` only. Set on the web or by an online registration token.\n   * Optional so a runner built by other code than this plugin's server needs none; the server always sets it.\n   */\n  readonly toolSlots?: ToolSlots | null;\n  /**\n   * What it last reported per coding tool for the tools its own settings limit: how many runs of each it holds at most\n   * and could take now, within this application. Null or absent when it reported none (unknown: read as\n   * room left).\n   */\n  /** Last heartbeat free slots; updated runners report this application only. */\n  readonly globalFree?: number;\n  /** Actual capacity from the last heartbeat; absent until reported. */\n  readonly reportedSlots?: number;\n  readonly capacitySource?: 'online' | 'legacyLocal';\n  readonly capacityReportedAt?: string;\n  readonly draining?: 'updatePending' | 'pruning' | 'diskLow';\n  readonly toolLoad?: Readonly<Partial<Record<AgentTool, ToolLoad>>> | null;\n  /**\n   * Its owner (or a manager of runners) lets it take jobs: builds and other steps an application configures, run\n   * without a model. Off for every runner until someone turns it on; a job also needs the runner to report the job's\n   * feature (`jobs.build`).\n   */\n  readonly acceptJobs: boolean;\n  /**\n   * What its owner's local policy lets it take, as it reported it (protocol 7): the agents, subjects and repositories\n   * it accepts. Null when it reported none: it takes anything it is registered for. Work kinds it refuses outright are\n   * missing from its `features` instead.\n   */\n  readonly policy: RunnerPolicy | null;\n  /**\n   * The names of the variables it provides to a run that asks for them by name (variables kept \"from the runner\"):\n   * its local variables and the names its owner passes from its environment, as it last reported them. Names only.\n   * Null or absent when it reported none (a runner from before they were reported: unknown).\n   */\n  readonly variables?: readonly string[] | null;\n  /**\n   * The working directories it keeps for this application and the free space on the disk holding them, as it last\n   * reported them. Null or absent when it never reported any (a runner that does not report, or one that has not yet).\n   */\n  readonly workspaceUsage?: RunnerWorkspaceUsage | null;\n  /**\n   * The tools and models a run failed `modelUnavailable` with here: not offered here until the runner reports that\n   * tool's models differently. Null or absent for none.\n   */\n  readonly unavailableModels?: readonly UnavailableModel[] | null;\n  readonly quotaRevision: number;\n  readonly quotaUsage?: readonly RunnerQuotaUsage[] | null;\n  readonly lastSeenAt: string | null;\n  readonly createdAt: string;\n  readonly updatedAt: string;\n}\n\nexport interface RunnerQuotaUsage {\n  readonly tool: AgentTool;\n  readonly window: string;\n  readonly scope: 'tool' | 'provider' | 'model';\n  readonly target: string;\n  readonly usedPercent?: number;\n  readonly resetsAt: string | null;\n  readonly observedAt: string;\n  /** Whether this observation exhausted its window. */\n  readonly exhausted?: boolean;\n}\n\n/** Active quota blocks for a candidate; default models still obey tool blocks. */\nexport function quotaBlocks(\n  runner: Pick<Runner, 'unavailableModels'>,\n  entry: Pick<RunnerModelEntry, 'tool' | 'model'>,\n  now: number,\n): UnavailableModel[] {\n  const model = entry.model ? normalizeModel(entry.tool, entry.model) : '';\n  return (runner.unavailableModels ?? []).filter(\n    (mark) =>\n      mark.reason === 'toolQuota' &&\n      mark.tool === entry.tool &&\n      (!mark.resetsAt || Date.parse(mark.resetsAt) > now) &&\n      (mark.scope === 'tool' ||\n        (model !== '' &&\n          (mark.scope === 'provider'\n            ? model.split('/')[0] === mark.model\n            : model === mark.model))),\n  );\n}\n\n/** A tool and model a run failed `modelUnavailable` with on a runner (`Runner.unavailableModels`). */\nexport interface UnavailableModel {\n  readonly reason?: 'modelUnavailable' | 'toolQuota';\n  readonly scope?: 'tool' | 'provider' | 'model';\n  readonly window?: string;\n  readonly resetsAt?: string | null;\n  readonly tool: AgentTool;\n  /** Normalized (`normalizeModel`). */\n  readonly model: string;\n  readonly at: string;\n  /** The tool's models as the runner reported them then, normalized: a different report lifts the mark. */\n  readonly reported: readonly string[];\n}\n\n/** A runner's working directories, as it last reported them (`Runner.workspaceUsage`). */\nexport interface RunnerWorkspaceUsage {\n  /** Computed from reported directory sizes; not a new runner protocol field. */\n  readonly totalBytes?: number;\n  readonly sizeUnknownCount?: number;\n  readonly counts?: Readonly<\n    Record<'all' | 'active' | 'retained' | 'ended', number>\n  >;\n  readonly diskMeasuredAt?: string;\n  readonly intervalMs?: number;\n  /** The disk holding the runner's working directories; null when it did not say. */\n  readonly disk: RunnerWorkspaceDisk | null;\n  /** How many it keeps for this application. */\n  readonly count: number;\n  /** How many of those hold work that was never pushed, and are never removed on the application's word. */\n  readonly unpushedCount: number;\n  /** When directories were collected; null until the first directory report. */\n  readonly measuredAt: string | null;\n  /** This application's, most recently used first. */\n  readonly workspaces: readonly RunnerWorkspace[];\n}\n\n/** The disk holding a runner's working directories, as it reported it. */\nexport interface RunnerWorkspaceDisk {\n  readonly freeBytes: number;\n  readonly totalBytes: number;\n  /** What its owner keeps free; below it, the runner removes directories that may go. Null for nothing. */\n  readonly minFreeBytes: number | null;\n}\n\n/** One working directory a runner keeps for this application. */\nexport interface RunnerWorkspace {\n  readonly subjectKey?: string;\n  readonly sizeBytes?: number;\n  readonly decision?: WorkspaceDecision;\n  readonly cleanup?: WorkspaceCleanupResult;\n  /** The last run that worked in it. */\n  readonly runId?: string;\n  /** Where it is on the runner. */\n  readonly workDir: string;\n  /** It holds changes not committed, or commits the remote task branch lacks. */\n  readonly unpushed: boolean;\n  readonly lastUsedAt: string;\n  /** The subject its last run worked on; null when the run is unknown here. */\n  readonly subjectKind: string | null;\n  readonly subjectId: string | null;\n  /** The subject's work is over (it may be removed), goes on, or cannot be told (null). */\n  readonly settled: boolean | null;\n}\n\n/** A directory's display category; subject completion alone does not mean it can be removed. */\nexport function workspaceCategory(\n  workspace: RunnerWorkspace,\n): 'active' | 'retained' | 'ended' {\n  if (workspace.settled === false) return 'active';\n  if (\n    workspace.settled === true &&\n    !workspace.unpushed &&\n    (!workspace.cleanup || workspace.cleanup.reason === 'allowed')\n  )\n    return 'ended';\n  return 'retained';\n}\n\n/** What a runner takes work for, as the kind of work it serves names it: an agent, for agent runs. */\nexport interface RunnerWorkTarget {\n  readonly id: string;\n  readonly name: string;\n}\n\n/** One item a runner holds now: a run of the kind of work it serves, or a job. */\nexport interface RunnerHeldItem {\n  readonly id: string;\n  readonly kind: 'run' | 'job';\n  /** What it is, for people: the agent of a run, a job's title or kind. */\n  readonly title: string;\n  readonly status: 'dispatched' | 'running';\n  readonly startedAt: string | null;\n  /** Where the application shows what it works on; null when nowhere, or when the viewer may not see it. */\n  readonly path: string | null;\n}\n\n/** One of a runner's latest runs, for its page. */\nexport interface RunnerRecentRun {\n  readonly subjectLabel?: string | null;\n  readonly failureReason?: string | null;\n  readonly id: string;\n  /** The agent that ran. */\n  readonly title: string;\n  readonly status: RunStatus;\n  readonly startedAt: string | null;\n  readonly finishedAt: string | null;\n  readonly createdAt: string;\n  /** Where the application shows what it worked on; null when nowhere, or when the viewer may not see it. */\n  readonly path: string | null;\n}\n\n/** Opaque continuation values use the stored start time, including never-started runs. */\nexport interface RunnerRunsCursor {\n  readonly startedAt: string | null;\n  readonly id: string;\n}\n\nexport interface RunnerRunsPage {\n  readonly data: RunnerRecentRun[];\n  readonly meta: {\n    readonly nextCursor: string | null;\n    readonly total: number;\n  };\n}\n\n/**\n * A runner in the list, with what the viewer may do with it. What identifies its machine (the host name, the tools'\n * executable paths) is shown only to its owner, the managers of runners and anyone who may wake an agent: `hostname`\n * is null and the tools carry no `path` for everyone else.\n */\nexport interface RunnerSummary extends Omit<\n  Runner,\n  'hostname' | 'quotaRevision'\n> {\n  readonly canSeeMachine?: boolean;\n  /** Null when the viewer may not manage it. */\n  readonly hostname: string | null;\n  /** Runs it holds now. */\n  readonly activeRuns: number;\n  /** Jobs it holds now. */\n  readonly activeJobs: number;\n  /**\n   * The runs it holds now, by the coding tool each runs with; a tool it runs nothing of is left out. Absent when\n   * unknown (a summary built by other code than this plugin's server): no use per tool is shown.\n   */\n  readonly activeByTool?: Readonly<Partial<Record<AgentTool, number>>>;\n  /**\n   * What it takes work for, by what people configured and what it reported (for agent runs: the agents whose tool is\n   * enabled and signed in here, that are not limited to other runners, and that its owner's policy lets in).\n   */\n  readonly takes: readonly RunnerWorkTarget[];\n  /**\n   * The viewer may change it (its name, slots, coding tools and policy): its owner, or a manager of runners once its\n   * owner can no longer act (none recorded, or disabled or deleted). A manager does not change someone else's runner.\n   */\n  readonly canManage: boolean;\n  readonly canManageTools?: boolean;\n  /** The viewer may switch it between personal and shared: whoever may change it (`canManage`). */\n  readonly canChangeTrust: boolean;\n  /** The viewer may revoke it, and delete it once revoked: its owner, or a manager of runners in an emergency. */\n  readonly canRevoke: boolean;\n  readonly canClearQuota: boolean;\n  /** Exact run count, without loading row details. */\n  readonly recentRunsCount: number;\n  /**\n   * A newer runner version the application serves for its platform, which the runner installs on its own between\n   * runs; null when it is up to date or the application serves none.\n   */\n  readonly updateVersion: string | null;\n  /** The protocols this application serves; a runner speaking another one is `upgrade_required`. */\n  readonly requiredProtocol: { readonly min: number; readonly max: number };\n  /**\n   * The application gives runners jobs (it registered job kinds, such as an application's runner build method): only then is\n   * whether a runner takes them (`acceptJobs`) worth showing.\n   */\n  readonly offersJobs: boolean;\n}\n\n/** The list carries totals only; fetch a single runner for directory diagnostics. */\nexport const RUNNER_LIST_FIELDS = {\n  id: true,\n  name: true,\n  hostname: true,\n  os: true,\n  arch: true,\n  version: true,\n  product: true,\n  tools: true,\n  enabledTools: true,\n  trust: true,\n  ownerUserId: true,\n  ownerName: true,\n  status: true,\n  slots: true,\n  reportedSlots: true,\n  capacitySource: true,\n  capacityReportedAt: true,\n  toolLoad: true,\n  toolSlots: true,\n  activeRuns: true,\n  activeJobs: true,\n  activeByTool: true,\n  lastSeenAt: true,\n  draining: true,\n  canManage: true,\n  canManageTools: true,\n  canChangeTrust: true,\n  canRevoke: true,\n  takes: true,\n  updateVersion: true,\n} as const;\n\nexport interface RunnerListItem extends Pick<\n  RunnerSummary,\n  keyof typeof RUNNER_LIST_FIELDS\n> {\n  readonly takesCount: number;\n  readonly workspaceUsage?: Omit<RunnerWorkspaceUsage, 'workspaces'> | null;\n}\n\n/** The single public runtime-list projection; schema and type use the same field set. */\nexport function runnerListItem(\n  summary: Omit<RunnerSummary, 'recentRunsCount'>,\n): RunnerListItem {\n  const selected = Object.fromEntries(\n    Object.keys(RUNNER_LIST_FIELDS).map((key) => [\n      key,\n      summary[key as keyof typeof RUNNER_LIST_FIELDS],\n    ]),\n  ) as Pick<RunnerSummary, keyof typeof RUNNER_LIST_FIELDS>;\n  const totals = summary.workspaceUsage\n    ? (({ workspaces: _rows, ...rest }) => rest)(summary.workspaceUsage)\n    : null;\n  return {\n    ...selected,\n    tools: summary.tools.map(({ kind, version, authenticated }) => ({\n      kind,\n      version,\n      authenticated,\n    })),\n    takes: summary.takes.slice(0, 3),\n    takesCount: summary.takes.length,\n    workspaceUsage: summary.workspaceUsage ? totals : null,\n  };\n}\n\nexport interface RunnerWorkspacePage {\n  readonly data: readonly RunnerWorkspace[];\n  readonly meta: {\n    readonly total: number;\n    readonly page: number;\n    readonly pageSize: number;\n    readonly usage: Omit<RunnerWorkspaceUsage, 'workspaces'> | null;\n  };\n}\n\n/** What people change about a runner after it registered. */\nexport interface RunnerPatch {\n  readonly name?: string;\n  readonly trust?: RunnerTrust;\n  readonly slots?: number;\n  /** Limits per coding tool; null, or a tool left out, for none of its own (bounded by `slots`). */\n  readonly toolSlots?: ToolSlots | null;\n  /** null offers every tool the runner reports. */\n  readonly redetectTools?: boolean;\n  readonly enabledTools?: readonly AgentTool[] | null;\n  readonly acceptJobs?: boolean;\n}\n\nexport interface RegistrationTokenInput {\n  /** `team` needs the `agents.runners` manage permission; anyone may add a personal runner. */\n  readonly trust?: RunnerTrust;\n  /** The coding tools the runner that registers with this token may run; omitted or null for every tool. */\n  readonly enabledTools?: readonly AgentTool[] | null;\n  /**\n   * How many runs at once the runner that registers with this token takes (1 to 64); omitted or null defaults to three.\n   */\n  readonly slots?: number | null;\n  /**\n   * The limits per coding tool the runner that registers with this token gets; omitted or null for none. A runner\n   * cannot override these online tool limits with legacy local settings.\n   */\n  readonly toolSlots?: ToolSlots | null;\n}\n\n/** A one-time registration token; `token` is shown only in this answer. */\nexport interface RegistrationToken {\n  readonly id: string;\n  readonly token: string;\n  readonly trust: RunnerTrust;\n  readonly enabledTools: readonly AgentTool[] | null;\n  readonly slots: number | null;\n  /** Absent from tokens made before limits per tool, or built by other code: none. */\n  readonly toolSlots?: ToolSlots | null;\n  readonly expiresAt: string;\n}\n\n/** Usable token metadata; the secret and its hash are never returned by a list. */\nexport interface RegistrationTokenSummary extends Omit<\n  RegistrationToken,\n  'token'\n> {\n  readonly createdById: string | null;\n  readonly createdAt: string;\n}\n\n/**\n * A short-lived token that lets the install script download the `acme` CLI for one platform (the one its first\n * download names) and nothing else; `token` is shown only in this answer. It registers no runner.\n */\nexport interface DownloadToken {\n  readonly token: string;\n  readonly expiresAt: string;\n  /** How many tarball downloads it allows, retries included. */\n  readonly maxDownloads: number;\n}\n\n/** Whether the explicit server selection permits `tool`; null API input is normalized to the four native tools. */\nexport function toolEnabled(\n  runner: Pick<Runner, 'enabledTools'>,\n  tool: AgentTool,\n): boolean {\n  return (runner.enabledTools ?? NATIVE_AGENT_TOOLS).includes(tool);\n}\n\n/** Whether `runner` can run `tool`'s work: it is enabled there, installed and signed in. */\nexport function runsTool(\n  runner: Pick<Runner, 'enabledTools' | 'tools'>,\n  tool: AgentTool,\n): boolean {\n  return (\n    toolEnabled(runner, tool) &&\n    runner.tools.some(\n      (item) =>\n        item.kind === tool &&\n        item.authenticated &&\n        (!item.status || item.status === 'ready'),\n    )\n  );\n}\n\n/**\n * The models a runner reports for `tool`, normalized and each once, when the tool is enabled there and signed in;\n * empty otherwise, and when the runner reported no models.\n */\nexport function reportedModels(\n  runner: Pick<Runner, 'enabledTools' | 'tools'>,\n  tool: AgentTool,\n): string[] {\n  if (!runsTool(runner, tool)) return [];\n  const info = runner.tools.find(\n    (item) => item.kind === tool && item.authenticated,\n  );\n  if (!isNativeTool(tool) && info?.modelsDetectionStatus === 'unsupported')\n    return [''];\n  return [\n    ...new Set(\n      (info?.models ?? []).map((model) => normalizeModel(tool, model.id)),\n    ),\n  ];\n}\n\n/**\n * Whether `runner` can run `entry`: its tool enabled, installed and signed in, and, for an entry naming a model, the\n * model among those the runner reports for the tool and not marked unavailable there (`unavailableModels`).\n */\nexport function runsEntry(\n  runner: Pick<Runner, 'enabledTools' | 'tools' | 'unavailableModels'>,\n  entry: Pick<RunnerModelEntry, 'tool' | 'model'>,\n  now: number,\n): boolean {\n  if (\n    !runsTool(runner, entry.tool) ||\n    quotaBlocks(runner, entry, now).length > 0\n  )\n    return false;\n  if (!entry.model) return true;\n  const model = normalizeModel(entry.tool, entry.model);\n  return (\n    reportedModels(runner, entry.tool).includes(model) &&\n    !(runner.unavailableModels ?? []).some(\n      (mark) =>\n        mark.reason !== 'toolQuota' &&\n        mark.tool === entry.tool &&\n        mark.model === model,\n    )\n  );\n}\n\n/** The job kinds a runner reports it executes (`jobs.<kind>` features). */\nexport function jobKindsOf(runner: Pick<Runner, 'features'>): string[] {\n  return runner.features\n    .filter((feature) => feature.startsWith('jobs.'))\n    .map((feature) => feature.slice('jobs.'.length));\n}\n\n/** The state of one of a runner's coding tools, as a page shows it. */\nexport type ToolState =\n  'off' | 'notInstalled' | 'signedOut' | 'signedIn' | 'checking' | 'failed';\n\n/** Off when people turned it off here; otherwise whether the runner has it installed and signed in. */\nexport function toolState(\n  runner: Pick<Runner, 'enabledTools' | 'tools'>,\n  tool: AgentTool,\n): ToolState {\n  if (!toolEnabled(runner, tool)) return 'off';\n  const info = runner.tools.find((item) => item.kind === tool);\n  if (!info) return 'checking';\n  if (\n    info.status === 'notInstalled' ||\n    info.status === 'checking' ||\n    info.status === 'failed'\n  )\n    return info.status;\n  return info.authenticated ? 'signedIn' : 'signedOut';\n}\n\n/** The selected or reported tools, in catalog order, including selected tools awaiting detection. */\nexport function listedTools(\n  runner: Pick<Runner, 'tools'> & Partial<Pick<Runner, 'enabledTools'>>,\n): AgentTool[] {\n  return AGENT_TOOLS.filter(\n    (tool) =>\n      runner.tools.some((item) => item.kind === tool) ||\n      (runner.enabledTools ?? []).includes(tool),\n  );\n}\n\n/**\n * How a runner reads at a glance: `busy` is online with every slot taken. Revoked and upgrade-required runners take\n * no work whatever their slots say.\n */\nexport type RunnerActivity =\n  | 'online'\n  | 'busy'\n  | 'low_disk'\n  | 'offline'\n  | 'revoked'\n  | 'upgrade_required'\n  | 'updatePending'\n  | 'pruning';\n\nexport function runnerActivity(\n  runner: Pick<\n    RunnerListItem,\n    | 'status'\n    | 'slots'\n    | 'activeRuns'\n    | 'activeJobs'\n    | 'workspaceUsage'\n    | 'draining'\n  >,\n): RunnerActivity {\n  if (runner.status !== 'online') return runner.status;\n  if (runner.draining === 'diskLow') return 'low_disk';\n  if (runner.draining) return runner.draining;\n  if (runnerLowOnDisk(runner)) return 'low_disk';\n  return runner.activeRuns + runner.activeJobs >= runner.slots\n    ? 'busy'\n    : 'online';\n}\n\n/** How many runs of `tool` the runner may hold at once: its limit for the tool, never above its total slots. */\nexport function toolLimit(\n  runner: Pick<Runner, 'slots' | 'toolSlots'>,\n  tool: AgentTool,\n): number {\n  const own = runner.toolSlots?.[tool];\n  return own === undefined ? runner.slots : Math.min(own, runner.slots);\n}\n\n/** One coding tool's use of a runner's slots, as a page shows it. */\nexport interface ToolUsage {\n  readonly tool: AgentTool;\n  /** Runs of it the runner holds now, for this application. */\n  readonly used: number;\n  /** Its limit (`toolLimit`). */\n  readonly limit: number;\n  /** Whether the limit is its own (`toolSlots`) rather than the runner's total. */\n  readonly limited: boolean;\n}\n\n/**\n * The coding tools worth showing a runner's use of, in the protocol's order: those with a limit of their own and those\n * it runs something of now. Empty for a runner without limits per tool that runs nothing.\n */\nexport function toolUsage(\n  runner: Pick<RunnerSummary, 'slots' | 'toolSlots' | 'activeByTool'>,\n): ToolUsage[] {\n  return AGENT_TOOLS.flatMap((tool) => {\n    const used = runner.activeByTool?.[tool] ?? 0;\n    const limited = runner.toolSlots?.[tool] !== undefined;\n    return limited || used > 0\n      ? [{ tool, used, limit: toolLimit(runner, tool), limited }]\n      : [];\n  });\n}\n\n/** An agent as far as where it may run is concerned (the agents plugin's `Agent` fits). */\nexport interface RunnerAgentFit {\n  readonly id: string;\n  readonly name: string;\n  /** Its coding tools and models, in order. */\n  readonly modelEntries: readonly RunnerModelEntry[];\n}\n\n/**\n * Whether `runner` may take `agent`'s runs, by what it reported: one of the agent's tools and models is enabled, signed\n * in and reported here (`runsEntry`), and the owner's local policy lets it in. Whether the runner is online right now is\n * left to the caller.\n */\n/** Shared by admission, availability and the page; does not affect existing leases. */\nexport function runnerLowOnDisk(\n  runner: Pick<RunnerListItem, 'workspaceUsage'>,\n): boolean {\n  const disk = runner.workspaceUsage?.disk;\n  return (\n    disk != null &&\n    disk.minFreeBytes !== null &&\n    disk.freeBytes < disk.minFreeBytes\n  );\n}\n\nexport function runnerTakesAgent(\n  runner: Pick<\n    Runner,\n    | 'id'\n    | 'enabledTools'\n    | 'tools'\n    | 'policy'\n    | 'unavailableModels'\n    | 'workspaceUsage'\n  >,\n  agent: RunnerAgentFit,\n  now: number,\n): boolean {\n  return (\n    !runnerLowOnDisk(runner) &&\n    agent.modelEntries.some((entry) => runsEntry(runner, entry, now)) &&\n    policyAllowsAgent(runner.policy, agent)\n  );\n}\n\n/** Quota information for runtimes that otherwise fit; unrelated personal machines stay private. */\nexport function quotaForAgent(\n  runners: readonly Runner[],\n  agent: RunnerAgentFit,\n  actorUserId: string | undefined,\n  now: number,\n): QuotaLocation[] {\n  return runners.flatMap((runner) => {\n    if (\n      !(runner.unavailableModels ?? []).some(\n        (mark) =>\n          mark.reason === 'toolQuota' &&\n          (!mark.resetsAt || Date.parse(mark.resetsAt) > now),\n      )\n    )\n      return [];\n    if (\n      runner.trust !== 'team' &&\n      actorUserId !== undefined &&\n      runner.ownerUserId !== actorUserId\n    )\n      return [];\n    const compatible = {\n      ...runner,\n      unavailableModels: (runner.unavailableModels ?? []).filter(\n        (mark) => mark.reason !== 'toolQuota',\n      ),\n    };\n    if (!runnerTakesAgent(compatible, agent, now)) return [];\n    const blocks = agent.modelEntries\n      .filter((entry) => runsEntry(compatible, entry, now))\n      .map((entry) => quotaBlocks(runner, entry, now));\n    if (blocks.some((list) => !list.length)) return [];\n    const resets = blocks.map((list) =>\n      list.some((mark) => !mark.resetsAt)\n        ? null\n        : new Date(\n            Math.max(...list.map((mark) => Date.parse(mark.resetsAt!))),\n          ).toISOString(),\n    );\n    return [\n      {\n        runnerId: runner.id,\n        runnerName: runner.name,\n        resetsAt:\n          resets.filter((reset): reset is string => reset !== null).sort()[0] ??\n          null,\n      },\n    ];\n  });\n}\n\n/** Reuse the directory snapshot already read for detail; list reads keep their small JSON projection. */\nexport function workspaceSummary(\n  usage: RunnerWorkspaceUsage,\n): RunnerWorkspaceUsage {\n  const counts = { all: usage.count, active: 0, retained: 0, ended: 0 };\n  let totalBytes = 0,\n    sizeUnknownCount = 0;\n  for (const workspace of usage.workspaces) {\n    counts[workspaceCategory(workspace)]++;\n    if (workspace.sizeBytes === undefined) sizeUnknownCount++;\n    else totalBytes += workspace.sizeBytes;\n  }\n  return { ...usage, totalBytes, sizeUnknownCount, counts };\n}\n\n/** Undefined means capabilities are unknown; an empty list is a known empty intersection. */\nexport function chatEffortCapabilities(\n  entry: RunnerModelEntry | undefined,\n  runners: readonly Pick<Runner, 'tools'>[],\n): readonly string[] | undefined {\n  if (!entry?.model || runners.length === 0) return undefined;\n  const reports = runners.map(\n    (runner) =>\n      runner.tools\n        .find((tool) => tool.kind === entry.tool)\n        ?.models?.find(\n          (model) =>\n            normalizeModel(entry.tool, model.id) ===\n            normalizeModel(entry.tool, entry.model!),\n        )?.efforts,\n  );\n  const known = reports.filter((report) => report !== undefined);\n  const options = effortsFor(entry).filter((effort) =>\n    known.every((report) => report.includes(effort)),\n  );\n  // Missing reports cannot widen an already empty intersection of known capabilities.\n  return options.length === 0 || known.length === reports.length\n    ? options\n    : undefined;\n}\n\n/** Known efforts common to every eligible runner; unknown reports hide selection. */\nexport function chatEffortsFor(\n  entry: RunnerModelEntry | undefined,\n  runners: readonly Pick<Runner, 'tools'>[],\n): readonly string[] {\n  return chatEffortCapabilities(entry, runners) ?? [];\n}\n"
