dating = false;\n    }\n  }\n\n  /** Asks one application for up to `free` runs and starts them. Returns how many it got. */\n  private async claimFrom(\n    link: AppLink,\n    free: number,\n    wait: boolean,\n  ): Promise<number> {\n    if (\n      !link.heartbeatHealthy ||\n      link.revoked ||\n      link.upgradeRequired ||\n      this.pendingUpdate ||\n      this.pruning ||\n      this.holdingForPrune ||\n      this.diskPaused ||\n      this.stopping.signal.aborted\n    )\n      return 0;\n    const settings = await readSettings(this.options.paths);\n    const disk = await (this.options.readDisk ?? readDisk)(\n      this.options.paths.workRoot,\n    );\n    if (\n      this.holdingForPrune ||\n      !link.heartbeatHealthy ||\n      link.revoked ||\n      link.upgradeRequired ||\n      this.pendingUpdate ||\n      this.pruning ||\n      this.diskPaused ||\n      this.stopping.signal.aborted\n    )\n      return 0;\n    if (lowOnDisk(disk, minFreeDisk(settings))) {\n      await this.collectGarbage();\n      return 0;\n    }\n    this.claimsInFlight += 1;\n    try {\n      return await this.claimAndStart(\n        link,\n        Math.min(free, this.free(link)),\n        wait,\n      );\n    } finally {\n      this.claimsInFlight -= 1;\n      if (this.claimsInFlight === 0) {\n        this.claimsDrained?.();\n        this.claimsDrained = undefined;\n      }\n      void this.pruneStore();\n    }\n  }\n\n  /** Receives leases and starts their workers while `claimFrom` excludes pruning. */\n  private async claimAndStart(\n    link: AppLink,\n    free: number,\n    wait: boolean,\n  ): Promise<number> {\n    const pollTimeout =\n      this.timings.pollTimeoutMs ?? link.connection.registration.pollTimeoutMs;\n    const response: ClaimResponse = await link.client.post(\n      RUNNER_ROUTES.claim,\n      {\n        free,\n        ...(Object.keys(link.capacity?.toolSlots ?? {}).length > 0\n          ? { tools: this.toolRoom(link) }\n          : {}),\n      },\n      ClaimResponseSchema,\n      {\n        ...(wait ? { query: { wait: 'true' } } : {}),\n        timeoutMs: pollTimeout + 10_000,\n        signal: this.stopping.signal,\n      },\n    );\n    // What the owner's local policy does not take is given back at once, to be retried on another runner.\n    const policy = await this.policyOf(link);\n    for (const payload of response.jobs ?? []) {\n      if (this.stopping.signal.aborted) break;\n      const refused = refuseJob(\n        policy.policy,\n        payload,\n        policy.isolationProblem,\n      );\n      if (refused !== undefined) {\n        this.options.log(`job ${payload.job.id}: refused: ${refused}`);\n        await link.client\n          .request(\n            'POST',\n            routePath(RUNNER_ROUTES.jobFail, { jobId: payload.job.id }),\n            { reason: 'policyRefused', detail: refused },\n          )\n          .catch(() => undefined);\n        continue;\n      }\n      try {\n        await this.supervisor.spawnJob(link.key, payload);\n      } catch (error) {\n        this.options.log(\n          `job ${payload.job.id}: could not start: ${error instanceof Error ? error.message : String(error)}`,\n        );\n        await link.client\n          .request(\n            'POST',\n            routePath(RUNNER_ROUTES.jobFail, { jobId: payload.job.id }),\n            {\n              reason: isDiskFull(error) ? 'runnerDiskFull' : 'startTimeout',\n              detail: `The runner could not start a worker: ${error instanceof Error ? error.message : String(error)}`,\n            },\n          )\n          .catch(() => undefined);\n      }\n    }\n    for (const payload of response.runs) {\n      if (this.stopping.signal.aborted) break;\n      const refused = !(\n        link.connection.registration.enabledTools ?? []\n      ).includes(payload.tool.kind)\n        ? 'The coding tool is disabled for this runner.'\n        : refuseRun(policy.policy, payload);\n      if (refused !== undefined) {\n        this.options.log(`run ${payload.run.id}: refused: ${refused}`);\n        await link.client\n          .request(\n            'POST',\n            routePath(RUNNER_ROUTES.fail, { runId: payload.run.id }),\n            { reason: 'policyRefused', detail: refused },\n          )\n          .catch(() => undefined);\n        continue;\n      }\n      // An application that does not know limits per tool may hand over a run of a full tool: it runs all the same.\n      const limit = link.capacity?.toolSlots[payload.tool.kind];\n      if (\n        limit !== undefined &&\n        this.held(link, payload.tool.kind) >=\n          this.toolLimit(link, payload.tool.kind)\n      )\n        this.options.log(\n          `run ${payload.run.id}: ${payload.tool.kind} is over its limit of ${this.toolLimit(link, payload.tool.kind)}; ${link.key} does not apply limits per tool`,\n        );\n      try {\n        const tools = (await link.detection?.capabilities)?.tools;\n        await this.supervisor.spawn(\n          link.key,\n          payload,\n          tools?.find((tool) => tool.kind === payload.tool.kind)?.version,\n        );\n      } catch (error) {\n        this.options.log(\n          `run ${payload.run.id}: could not start: ${error instanceof Error ? error.message : String(error)}`,\n        );\n        await link.client\n          .request(\n            'POST',\n            routePath(RUNNER_ROUTES.fail, { runId: payload.run.id }),\n            {\n              reason: isDiskFull(error)\n                ? 'runnerDiskFull'\n                : error instanceof WorkspaceBusyError &&\n                    payload.run.acceptedFailures?.includes('workspaceBusy')\n                  ? 'workspaceBusy'\n                  : 'startTimeout',\n              detail: `The runner could not start a worker: ${error instanceof Error ? error.message : String(error)}`,\n            },\n          )\n          .catch(() => undefined);\n      }\n    }\n    return response.runs.length + (response.jobs?.length ?? 0);\n  }\n\n  private async claim(): Promise<void> {\n    const { log } = this.options;\n    const fallback = this.timings.pollFallbackMs ?? 15_000;\n    const rotation = this.timings.rotationIntervalMs ?? 3_000;\n    let failures = 0;\n    while (!this.stopping.signal.aborted) {\n      if (this.live.length === 0) break;\n      const live = this.claimable;\n      if (live.length === 0) {\n        // No application has a usable heartbeat configuration; a successful heartbeat wakes this wait.\n        await this.pause(fallback);\n        continue;\n      }\n      if (\n        live.every((link) => this.free(link) <= 0) ||\n        this.pendingUpdate ||\n        this.pruning ||\n        this.holdingForPrune ||\n        this.diskPaused\n      ) {\n        await new Promise<void>((resolve) => {\n          this.slotFreed = resolve;\n        });\n        this.slotFreed = undefined;\n        continue;\n      }\n      const single = live.length === 1;\n      const wakeSignal = this.wakeController.signal;\n      const startedAt = Date.now();\n      let claimed = 0;\n      for (let step = 0; step < live.length; step += 1) {\n        if (this.stopping.signal.aborted) break;\n        const link = live[(this.nextApp + step) % live.length];\n        const free = this.free(link);\n        if (free <= 0) continue;\n        try {\n          const count = await this.claimFrom(link, free, single);\n          failures = 0;\n          if (count > 0) {\n            claimed += count;\n            this.nextApp = (this.nextApp + step + 1) % live.length;\n          }\n        } catch (error) {\n          if (this.stopping.signal.aborted) break;\n          if (error instanceof ApiError && REVOKED.has(error.reason)) {\n            await this.revoke(link, error.reason, error.message);\n            continue;\n          }\n          if (error instanceof ApiError && error.reason === UNSUPPORTED) {\n            this.setUpgradeRequired(link, true, error.message);\n            continue;\n          }\n          failures += 1;\n          log(\n            `${link.key}: claim failed: ${error instanceof Error ? error.message : String(error)}`,\n          );\n          if (single) await this.pause(backoff(failures, 1_000, 15_000));\n        }\n      }\n      if (\n        wakeSignal.aborted ||\n        claimed > 0 ||\n        live.every((link) => this.free(link) <= 0)\n      )\n        continue;\n      if (single) {\n        const elapsed = Date.now() - startedAt;\n        const pollTimeout =\n          this.timings.pollTimeoutMs ??\n          live[0].connection.registration.pollTimeoutMs;\n        if (elapsed < Math.min(fallback, pollTimeout) / 2)\n          await this.pause(fallback - elapsed);\n      } else {\n        await this.pause(\n          failures > 0 ? backoff(failures, rotation, 15_000) : rotation,\n        );\n      }\n    }\n  }\n}\n"
    },
    {
      "path": "packages/app/agent-runner/src/agent/adapters/registry.ts",
      "content": "// The adapters this runner can start, by tool kind.\n//\n// Claude Code, Codex, OpenCode and Pi all have real adapters. `NOCOBASE_RUNNER_ADAPTER=echo` makes the echo adapter stand in for every\n// tool kind, which is how the tests and local development drive the runner without a coding tool.\nimport { AGENTS } from '@nocobase/acp-bridge/catalog';\nimport { createAcpAdapter } from './acp.ts';\nimport { AGENT_TOOLS, type AgentTool } from '../../protocol/index.ts';\nimport { detectionEnv } from '../env.ts';\nimport { createClaudeAdapter } from './claude.ts';\nimport { createCodexAdapter } from './codex.ts';\nimport { createEchoAdapter } from './echo.ts';\nimport { createOpencodeAdapter } from './opencode.ts';\nimport { createPiAdapter } from './pi.ts';\nimport type { AgentAdapter } from './types.ts';\n\nconst nativeAdapters = new Map<\n  string,\n  (options: { env: Record<string, string> }) => AgentAdapter\n>([\n  ['claude', createClaudeAdapter],\n  ['codex', createCodexAdapter],\n  ['opencode', createOpencodeAdapter],\n  ['pi', createPiAdapter],\n]);\n\n/**\n * The adapters, detecting their tools in the environment a run gets from the runner (`detectionEnv`): `env` and the\n * names the runner's owner passes (`--pass-env`) and the application's local variables.\n */\nexport function loadAdapters(\n  env: NodeJS.ProcessEnv = process.env,\n  passEnv: readonly string[] = [],\n  localVariables: Record<string, string> = {},\n  selected: readonly AgentTool[] = AGENT_TOOLS,\n): Map<AgentTool, AgentAdapter> {\n  const adapters = new Map<AgentTool, AgentAdapter>();\n  if (env.NOCOBASE_RUNNER_ADAPTER === 'echo') {\n    for (const kind of selected.filter((id) => AGENT_TOOLS.includes(id)))\n      adapters.set(kind, createEchoAdapter({ kind }));\n    return adapters;\n  }\n  const detection = { env: detectionEnv(env, passEnv, localVariables) };\n  for (const kind of selected) {\n    const factory = nativeAdapters.get(kind);\n    const spec = AGENTS.find((agent) => agent.id === kind);\n    if (kind === 'claude')\n      adapters.set(\n        kind,\n        createClaudeAdapter({\n          ...detection,\n          nonessentialTraffic:\n            env.NOCOBASE_RUNNER_CLAUDE_NONESSENTIAL_TRAFFIC === '1',\n        }),\n      );\n    else if (factory) {\n      adapters.set(kind, factory(detection));\n    } else if (spec) adapters.set(kind, createAcpAdapter(spec, detection.env));\n    else throw new Error(`Unknown coding tool: ${kind}`);\n  }\n  return adapters;\n}\n"
    },
    {
      "path": "packages/libs/acp-bridge/src/agent-process.ts",
      "content": "/**\n * One agent process speaking ACP over its standard input and output, with the bridge as its client. Stopping it also\n * stops the shells and servers it started: it runs in a process group of its own, which is signalled, or on Windows its\n * process tree is ended with `taskkill`.\n */\nimport {\n  execFile,\n  spawn,\n  type ChildProcess,\n  type ChildProcessByStdio,\n} from 'node:child_process';\nimport { once } from 'node:events';\nimport { Readable, Writable } from 'node:stream';\n\nimport * as acp from '@agentclientprotocol/sdk';\n\nimport type { ResolvedAgent } from './agents.js';\n\nexport interface AgentClientHandlers {\n  readonly update: (notification: acp.SessionNotification) => void;\n  readonly permission: (\n    request: acp.RequestPermissionRequest,\n    signal: AbortSignal,\n  ) => Promise<acp.RequestPermissionResponse>;\n}\n\nexport interface AgentProcessOptions {\n  readonly signal?: AbortSignal | undefined;\n  readonly cwd: string;\n  readonly env: NodeJS.ProcessEnv;\n  readonly client: acp.Implementation;\n  readonly handlers: AgentClientHandlers;\n  readonly initializeTimeoutMs?: number;\n  /** False for an inspection that must not grant full-access environment defaults. */\n  readonly permissionDefaults?: boolean;\n}\n\n/** Long enough for an adapter that npx fetches on first use, when no managed one can run. */\nconst INITIALIZE_TIMEOUT_MS = 120_000;\nconst STOP_GRACE_MS = 3_000;\nconst STDERR_TAIL = 4_000;\n\nexport class AgentProcess {\n  readonly initialize: acp.InitializeResponse;\n  readonly #child: ChildProcess;\n  readonly #connection: acp.ClientConnection;\n  readonly #stderr: { text: string };\n  readonly #handlers: { current: AgentClientHandlers };\n  readonly #removeAbort: () => void;\n\n  private constructor(\n    child: ChildProcess,\n    connection: acp.ClientConnection,\n    stderr: { text: string },\n    handlers: { current: AgentClientHandlers },\n    initialize: acp.InitializeResponse,\n    removeAbort: () => void,\n  ) {\n    this.#child = child;\n    this.#connection = connection;\n    this.#stderr = stderr;\n    this.#handlers = handlers;\n    this.initialize = initialize;\n    this.#removeAbort = removeAbort;\n  }\n\n  /** Starts the agent and runs ACP `initialize`; throws with what the agent printed when it does not answer. */\n  static async start(\n    agent: ResolvedAgent,\n    options: AgentProcessOptions,\n  ): Promise<AgentProcess> {\n    options.signal?.throwIfAborted();\n    const child = startProgram(agent, options);\n    const stderr = { text: '' };\n    child.stderr.setEncoding('utf8');\n    child.stderr.on('data', (chunk: string) => {\n      stderr.text = (stderr.text + chunk).slice(-STDERR_TAIL);\n    });\n    const spawned = new Promise<void>((resolve, reject) => {\n      child.once('spawn', resolve);\n      child.once('error', reject);\n    });\n    const stream = acp.ndJsonStream(\n      Writable.toWeb(child.stdin),\n      Readable.toWeb(child.stdout),\n    );\n    // Read on every message, so a process handed to another owner (`handOver`) answers to it from then on.\n    const handlers = { current: options.handlers };\n    const connection = acp\n      .client({ name: options.client.name })\n      .onNotification(acp.methods.client.session.update, (context) =>\n        handlers.current.update(context.params),\n      )\n      .onRequest(acp.methods.client.session.requestPermission, (context) =>\n        handlers.current.permission(context.params, context.signal),\n      )\n      .connect(stream);\n    const abort = (): void => {\n      connection.close();\n      void stopProcess(child);\n    };\n    options.signal?.addEventListener('abort', abort, { once: true });\n    const removeAbort = (): void =>\n      options.signal?.removeEventListener('abort', abort);\n    try {\n      await spawned;\n      options.signal?.throwIfAborted();\n      // Writing to an agent that has exited fails with EPIPE; the exit itself is what the session reports.\n      child.on('error', ignore);\n      child.stdin.on('error', ignore);\n      const timeoutMs = options.initializeTimeoutMs ?? INITIALIZE_TIMEOUT_MS;\n      let cleanup = () => {};\n      const initialize = await new Promise<acp.InitializeResponse>(\n        (resolve, reject) => {\n          const onExit = () =>\n            reject(new Error('The agent exited before it answered.'));\n          const timer = setTimeout(\n            () =>\n              reject(\n                new Error(\n                  `The agent did not answer within ${timeoutMs / 1000} seconds.`,\n                ),\n              ),\n            timeoutMs,\n          );\n          const onAbort = () => reject(new Error('Agent detection cancelled.'));\n          cleanup = () => {\n            clearTimeout(timer);\n            child.off('exit', onExit);\n            options.signal?.removeEventListener('abort', onAbort);\n          };\n          options.signal?.addEventListener('abort', onAbort, { once: true });\n          if (options.signal?.aborted) onAbort();\n          child.once('exit', onExit);\n          connection.agent\n            .request(acp.methods.agent.initialize, {\n              protocolVersion: acp.PROTOCOL_VERSION,\n              clientCapabilities: {},\n              clientInfo: options.client,\n            })\n            .then(resolve, reject)\n            .finally(cleanup);\n        },\n      ).finally(() => cleanup());\n      if (initialize.protocolVersion !== acp.PROTOCOL_VERSION)\n        throw new Error(\n          `ACP protocol incompatibility: the agent selected ${initialize.protocolVersion}; this host supports ACP ${acp.PROTOCOL_VERSION}. Reported tool release: ${initialize.agentInfo?.version ?? 'unknown'}. Minimum supported tool release: unknown. Upgrade the tool and its ACP adapter to their latest releases, then refresh detection; consult their compatibility documentation if the mismatch persists.`,\n        );\n      return new AgentProcess(\n        child,\n        connection,\n        stderr,\n        handlers,\n        initialize,\n        removeAbort,\n      );\n    } catch (error) {\n      removeAbort();\n      connection.close();\n      await stopProcess(child);\n      throw new Error(withOutput(errorMessage(error), stderr.text), {\n        cause: error,\n      });\n    }\n  }\n\n  get agent(): acp.ClientContext {\n    return this.#connection.agent;\n  }\n\n  /** Whether the process is still running and connected. */\n  get alive(): boolean {\n    return (\n      this.#child.exitCode === null &&\n      this.#child.signalCode === null &&\n      !this.#connection.signal.aborted\n    );\n  }\n\n  /** The agent's name and version, as it reported them. */\n  get description(): string {\n    const info = this.initialize.agentInfo;\n    return info ? `${info.title ?? info.name} ${info.version}` : 'ACP agent';\n  }\n\n  /** `error` with the last lines the agent printed, when the error itself says little. */\n  explain(error: unknown): string {\n    return withOutput(errorMessage(error), this.alive ? '' : this.#stderr.text);\n  }\n\n  /**\n   * Gives the running process to another owner: its session updates and permission requests go to `handlers` from now\n   * on, and the signal it was started with no longer stops it.\n   */\n  handOver(handlers: AgentClientHandlers): void {\n    this.#removeAbort();\n    this.#handlers.current = handlers;\n  }\n\n  async stop(): Promise<void> {\n    this.#removeAbort();\n    this.#connection.close();\n    await stopProcess(this.#child);\n  }\n}\n\n/** An error's message, with the details an ACP error carries. */\nexport function errorMessage(error: unknown): string {\n  if (error instanceof acp.RequestError) {\n    const data = error.data as\n      { message?: unknown; details?: unknown } | string | undefined;\n    const detail =\n      typeof data === 'string'\n        ? data\n        : typeof data?.message === 'string'\n          ? data.message\n          : data?.details;\n    return typeof detail === 'string' &&\n      detail &&\n      !error.message.includes(detail)\n      ? `${error.message}: ${detail}`\n      : error.message;\n  }\n  return error instanceof Error ? error.message : String(error);\n}\n\n/** Whether `error` is ACP's \"authentication required\". */\nexport function isAuthRequired(error: unknown): boolean {\n  return (\n    (error instanceof acp.RequestError && error.code === -32000) ||\n    (error instanceof Error &&\n      error.cause !== undefined &&\n      error.cause !== error &&\n      isAuthRequired(error.cause))\n  );\n}\n\nfunction withOutput(message: string, output: string): string {\n  const tail = output.trim().split('\\n').slice(-5).join('\\n');\n  return tail ? `${message}\\n${tail}` : message;\n}\n\nfunction ignore(): void {}\n\nconst windows = process.platform === 'win32';\n\nfunction startProgram(\n  agent: ResolvedAgent,\n  options: AgentProcessOptions,\n): ChildProcessByStdio<Writable, Readable, Readable> {\n  const common = {\n    cwd: options.cwd,\n    env: {\n      ...options.env,\n      ...agent.spec.env,\n      ...(options.permissionDefaults === false ? {} : agent.spec.permissionEnv),\n      ...agent.env,\n    },\n    stdio: ['pipe', 'pipe', 'pipe'] as ['pipe', 'pipe', 'pipe'],\n  };\n  if (!windows)\n    return spawn(agent.command, [...agent.args], { ...common, detached: true });\n  // A batch file, as npm installs `npx` and agents' commands, runs only through cmd.exe, given one command line.\n  return /\\.(?:cmd|bat)$/iu.test(agent.command)\n    ? spawn([agent.command, ...agent.args].map(quoteForCmd).join(' '), {\n        ...common,\n        shell: true,\n        windowsHide: true,\n      })\n    : spawn(agent.command, [...agent.args], { ...common, windowsHide: true });\n}\n\n/** `value` as one argument of a cmd.exe command line. */\nfunction quoteForCmd(value: string): string {\n  return /^[\\w@+=:,./\\\\-]+$/u.test(value)\n    ? value\n    : `\"${value.replace(/\"/gu, '\"\"')}\"`;\n}\n\nasync function stopProcess(child: ChildProcess): Promise<void> {\n  if (child.pid === undefined) return;\n  const exited =\n    child.exitCode !== null || child.signalCode !== null\n      ? Promise.resolve()\n      : once(child, 'exit');\n  if (windows) {\n    if (child.exitCode !== null || child.signalCode !== null) return;\n    endTree(child.pid);\n    await exited;\n    return;\n  }\n  signalGroup(child.pid, 'SIGTERM');\n  let timer: NodeJS.Timeout | undefined;\n  const forced = new Promise<void>((resolve) => {\n    timer = setTimeout(() => {\n      signalGroup(child.pid!, 'SIGKILL');\n      resolve();\n    }, STOP_GRACE_MS);\n  });\n  await exited;\n  // A launcher can exit while its descendants still hold this isolated group.\n  // Keep the force deadline even when the direct child exited before stop was called.\n  if (groupExists(child.pid)) await forced;\n  clearTimeout(timer);\n}\n\nfunction groupExists(pid: number): boolean {\n  try {\n    process.kill(-pid, 0);\n    return true;\n  } catch {\n    return false;\n  }\n}\n\n/** Ends the process `pid` and every process it started, on Windows. */\nfunction endTree(pid: number): void {\n  execFile(\n    'taskkill',\n    ['/pid', String(pid), '/T', '/F'],\n    { windowsHide: true },\n    ignore,\n  );\n}\n\nfunction signalGroup(pid: number, signal: NodeJS.Signals): void {\n  try {\n    process.kill(-pid, signal);\n  } catch {\n    // Already gone.\n  }\n}\n"
    },
    {
      "path": "packages/app/agent-runner/src/agent/adapters/acp.ts",
      "content": "import { StreamOutput } from './stream-output.ts';\n/** Drives a catalog agent through the same ACP client used by personal sessions. */\nimport { execFile } from 'node:child_process';\nimport { AGENTS } from '@nocobase/acp-bridge/catalog';\nimport {\n  requireRecoverableSession,\n  sessionUnavailable,\n} from './session-recovery.ts';\nimport type { AgentSpec } from '@nocobase/acp-bridge/catalog';\nimport type { ResolvedAgent } from '@nocobase/acp-bridge/client';\nimport {\n  AgentProcess,\n  configureSession,\n  continueSession,\n  errorMessage,\n  isAuthRequired,\n  ModelSelectionError,\n  methods,\n  resolveAgent,\n  sessionModels,\n} from '@nocobase/acp-bridge/client';\nimport type { SessionNotification } from '@nocobase/acp-bridge/client';\nimport { programFingerprint } from './program-fingerprint.ts';\nimport { withDetectionEnvironment } from './detection.ts';\nimport { detectExec } from './detect-exec.ts';\nimport { EventQueue } from './echo.ts';\nimport { capInput, capText } from './codex/util.ts';\nimport type {\n  AdapterEvent,\n  AdapterHandle,\n  AdapterResult,\n  AdapterSession,\n  AgentAdapter,\n  ToolDetection,\n} from './types.ts';\nimport {\n  AcpToolModelSchema,\n  MAX_TOOL_MODELS,\n  MAX_STATUS_DETAIL_LENGTH,\n  createRedactor,\n  type ToolCapabilities,\n  type AgentTool,\n  type ToolStatusReason,\n} from '../../protocol/index.ts';\n\nconst CLIENT = { name: 'nocobase-runner', version: '1' };\n\n/** `message`, redacted and with its control characters stripped; empty becomes absent. */\nfunction sanitizeMessage(\n  message: string,\n  maxLength: number,\n): string | undefined {\n  const redacted = createRedactor()\n    .text(message)\n    // eslint-disable-next-line no-control-regex -- stripping the control characters the protocol schemas refuse.\n    .replace(/[\\u0000-\\u001f\\u007f]/gu, ' ')\n    .trim();\n  return redacted ? redacted.slice(0, maxLength) : undefined;\n}\n\n/** The tool's own words about a detection failure, cut to what `ToolInfo.statusDetail` accepts. */\nexport function statusDetailOf(message: string): string | undefined {\n  return sanitizeMessage(message, MAX_STATUS_DETAIL_LENGTH);\n}\n\n/** How long a run failure's message may be: generous enough for an ACP error's own detail, far under `FailRequest.detail`. */\nconst MAX_RUN_FAILURE_MESSAGE_LENGTH = 2000;\n\n/** The tool's own words about a run failure, in place of a one-size-fits-all placeholder. */\nexport function runFailureMessage(error: unknown, fallback: string): string {\n  return (\n    sanitizeMessage(errorMessage(error), MAX_RUN_FAILURE_MESSAGE_LENGTH) ??\n    fallback\n  );\n}\n\n/** How the ACP handshake or first session failed, when `error` says enough to tell. */\nexport function classifyHandshakeFailure(error: unknown): {\n  status: 'needsLogin' | 'failed';\n  reason?: ToolStatusReason;\n} {\n  if (isAuthRequired(error))\n    return { status: 'needsLogin', reason: 'notLoggedIn' };\n  const message = error instanceof Error ? error.message : String(error);\n  if (\n    /did not answer within|detection cancelled|agent exited before/iu.test(\n      message,\n    )\n  )\n    return { status: 'failed', reason: 'timeout' };\n  // A generic heuristic, not tool-specific wording confirmed against a real handshake failure (goose with no\n  // provider set, for one): most agents name the missing piece when they refuse to start a session over it.\n  if (\n    /\\bno (?:model|provider)\\b|\\bprovider\\b.{0,20}\\b(?:missing|not set|required)\\b|\\bnot configured\\b/iu.test(\n      message,\n    )\n  )\n    return { status: 'failed', reason: 'notConfigured' };\n  return { status: 'failed', reason: 'startFailed' };\n}\n\n/**\n * Whether `resolved` really is `spec`'s agent, when it declares `identify`: false when the program's own output to\n * the identify probe matches the reject pattern (another program of the same name). True when it declares none, or\n * the probe itself could not be run or timed out — an agent CLI that does not answer `identify.args` cleanly is for\n * its own handshake to fail on, not for this heuristic to guess about.\n */\nexport function identifyProgram(\n  resolved: ResolvedAgent,\n  spec: AgentSpec,\n  env: Record<string, string>,\n  signal: AbortSignal,\n): Promise<boolean> {\n  if (!spec.identify) return Promise.resolve(true);\n  const { args, reject, timeoutMs = 5000 } = spec.identify;\n  return new Promise((resolvePromise) => {\n    const child = execFile(\n      resolved.command,\n      args,\n      { env, timeout: timeoutMs, windowsHide: true },\n      (_error, stdout, stderr) =>\n        resolvePromise(!reject.test(`${stdout}${stderr}`)),\n    );\n    signal.addEventListener('abort', () => child.kill(), { once: true });\n  });\n}\n\nexport function createAcpAdapter(\n  spec: AgentSpec,\n  env: Record<string, string>,\n): AgentAdapter {\n  return {\n    kind: spec.id as AgentTool,\n    features: () => [],\n    fingerprint: async () => {\n      const resolved = await resolveAgent(spec, env);\n      return programFingerprint(resolved?.command, resolved?.args);\n    },\n    detect: (signal) => inspect(spec, env, signal),\n    start: (session) => start(spec, session),\n  };\n}\n\n/** The version reported by dsh's CLI, preserving prerelease identifiers. */\nasync function dshVersion(\n  command: string,\n  env: Record<string, string>,\n  signal: AbortSignal,\n): Promise<string | undefined> {\n  try {\n    const result = await detectExec(env)(command, ['--version'], { signal });\n    if (result.code !== 0) return undefined;\n    return result.stdout.match(\n      /(?:^|\\s)v?(\\d+\\.\\d+\\.\\d+(?:-[0-9A-Za-z.-]+)?(?:\\+[0-9A-Za-z.-]+)?)(?:\\s|$)/u,\n    )?.[1];\n  } catch {\n    return undefined;\n  }\n}\n\nasync function inspect(\n  spec: AgentSpec,\n  env: Record<string, string>,\n  stop?: AbortSignal,\n): Promise<ToolDetection & ToolCapabilities> {\n  const deadline = AbortSignal.timeout(30_000);\n  const signal = stop ? AbortSignal.any([stop, deadline]) : deadline;\n  signal.throwIfAborted();\n  const resolved = await resolveAgent(spec, env);\n  if (!resolved)\n    return { installed: false, authenticated: false, status: 'notInstalled' };\n  if (!(await identifyProgram(resolved, spec, env, signal)))\n    return {\n      installed: false,\n      authenticated: false,\n      status: 'notInstalled',\n      statusReason: 'otherProgram',\n      statusDetail: statusDetailOf(\n        `${resolved.command} answers to ${spec.identify!.args.join(' ')} like a different program.`,\n      ),\n    };\n  if (spec.id === 'dsh' && !env.DEEPSEEK_API_KEY?.trim())\n    return {\n      installed: true,\n      path: resolved.command,\n      authenticated: false,\n      status: 'needsLogin',\n      statusReason: 'notLoggedIn',\n      statusDetail: statusDetailOf(\n        'Set DEEPSEEK_API_KEY and pass it to the runner with --pass-env DEEPSEEK_API_KEY, then detect again.',\n      ),\n    };\n  const cliVersion =\n    spec.id === 'dsh'\n      ? await dshVersion(resolved.command, env, signal)\n      : undefined;\n  return withDetectionEnvironment(\n    signal,\n    async (cwd, guardedEnv) => {\n      let process: AgentProcess | undefined;\n      try {\n        process = await AgentProcess.start(resolved, {\n          cwd,\n          env: guardedEnv,\n          client: CLIENT,\n          signal,\n          initializeTimeoutMs: 30_000,\n          permissionDefaults: false,\n          handlers: {\n            update: () => {},\n            permission: () =>\n              Promise.resolve({ outcome: { outcome: 'cancelled' } }),\n          },\n        });\n        const opened = await process.agent.request(methods.agent.session.new, {\n          cwd,\n          mcpServers: [],\n        });\n        const models = spec.modelsAreNotModels\n          ? undefined\n          : sessionModels(opened);\n        const safe =\n          models === undefined\n            ? undefined\n            : [\n                ...new Map(\n                  models.slice(0, MAX_TOOL_MODELS).flatMap((model) => {\n                    const base = AcpToolModelSchema.safeParse({ id: model.id });\n                    if (!base.success) return [];\n                    const named = AcpToolModelSchema.safeParse(model);\n                    return [\n                      [\n                        model.id,\n                        named.success ? named.data : base.data,\n                      ] as const,\n                    ];\n                  }),\n                ).values(),\n              ];\n        const version =\n          spec.id === 'dsh'\n            ? cliVersion\n            : process.initialize.agentInfo?.version;\n        const safeVersion =\n          version &&\n          version.length <= 64 &&\n          createRedactor().text(version) === version\n            ? version\n            : undefined;\n        // Amp v0.9.0 initializes and opens sessions without checking credentials. Its authenticate implementation\n        // acknowledges a configured adapter key, but AUTH_REQUIRED says nothing about the native CLI's accounts.\n        // See https://github.com/tao12345666333/amp-acp/blob/v0.9.0/src/server.ts#L218 and src/index.ts#L171.\n        // Never infer state from authMethods, including an empty list. Unknown implementations remain failed.\n        if (spec.signInUnconfirmable) {\n          const check = spec.authenticationCheck;\n          const supported =\n            check &&\n            process.initialize.agentInfo?.name === check.agentName &&\n            check.versions.includes(safeVersion ?? '');\n          let confirmed = false;\n          let detail = `${spec.name} ${safeVersion ?? '(release unknown)'} has no reviewed noninteractive authentication check. The handshake cannot confirm login; use an adapter with a supported authentication check, then detect again.`;\n          if (supported) {\n            try {\n              await process.agent.request(methods.agent.authenticate, {\n                methodId: check.methodId,\n              });\n              confirmed = true;\n            } catch (error) {\n              detail = isAuthRequired(error)\n                ? check.unconfirmedDetail\n                : `${spec.name}'s authentication check failed: ${errorMessage(error)}`;\n            }\n          }\n          if (!confirmed)\n            return {\n              installed: true,\n              path: resolved.command,\n              version: safeVersion,\n              authenticated: false,\n              status: 'failed',\n              statusReason: 'signInUnconfirmed',\n              statusDetail: statusDetailOf(detail),\n            };\n        }\n        return {\n          installed: true,\n          path: resolved.command,\n          version: safeVersion,\n          authenticated: true,\n          status: 'ready',\n          ...(safe ? { models: safe } : {}),\n          modelsDetectionStatus:\n            models === undefined\n              ? 'unsupported'\n              : models.length > 0 && !safe?.length\n                ? 'failed'\n                : 'detected',\n          modelsDetectedAt: new Date().toISOString(),\n        };\n      } catch (error) {\n        const classified = classifyHandshakeFailure(error);\n        const detail = statusDetailOf(\n          error instanceof Error ? error.message : String(error),\n        );\n        return {\n          installed: true,\n          path: resolved.command,\n          authenticated: false,\n          status: classified.status,\n          ...(classified.reason ? { statusReason: classified.reason } : {}),\n          ...(detail ? { statusDetail: detail } : {}),\n        };\n      } finally {\n        await process?.stop();\n      }\n    },\n    env,\n    { guardHostCli: true },\n  );\n}\n\n/** How long a run of same-typed text/thinking chunks may accumulate before it becomes one event. */\nconst MERGE_FLUSH_MS = 1000;\n/** How large the accumulated text of one merged event may grow before it flushes early. */\nconst MERGE_FLUSH_BYTES = 4 * 1024;\n\nfunction start(spec: AgentSpec, session: AdapterSession): AdapterHandle {\n  const events = new EventQueue<AdapterEvent>();\n  let process: AgentProcess | undefined;\n  let sessionId: string | undefined;\n  let replaying = false;\n  let cancelled = false;\n  let finished = false;\n  let summary = '';\n  const opening = new AbortController();\n  const toolCalls = new Map<\n    string,\n    { name: string; input: unknown; finished: boolean }\n  >();\n  const emit = (event: Omit<AdapterEvent, 'at'>): void => {\n    if (replaying || finished) return;\n    const content =\n      event.content === undefined || event.meta?.output\n        ? undefined\n        : capText(event.content);\n    const output =\n      event.output === undefined ? undefined : capText(event.output);\n    const input = event.input === undefined ? undefined : capInput(event.input);\n    events.push({\n      ...event,\n      ...(content ? { content: content.text } : {}),\n      ...(output ? { output: output.text } : {}),\n      ...(input ? { input: input.input } : {}),\n      meta: {\n        ...event.meta,\n        ...(content?.truncated || output?.truncated || input?.truncated\n          ? { truncated: true }\n          : {}),\n      },\n      at: new Date().toISOString(),\n    });\n  };\n  const streaming = new StreamOutput(emit);\n  let chunkId = 0;\n  let chunkType: 'text' | 'thinking' | undefined;\n  let streamPieces: string[] = [];\n  const flushStreamChunk = (interrupted = false): void => {\n    if (chunkType) {\n      if (interrupted) streaming.close(String(chunkId));\n      else\n        streaming.complete(String(chunkId), chunkType, streamPieces.join(''));\n    }\n    streamPieces = [];\n    chunkType = undefined;\n  };\n  const emitStreamChunk = (type: 'text' | 'thinking', text: string): void => {\n    if (replaying || finished) return;\n    if (chunkType !== type) {\n      flushStreamChunk();\n      chunkType = type;\n      chunkId++;\n    }\n    streamPieces.push(text);\n    streaming.delta(String(chunkId), type, text);\n  };\n  // Zed-style agents stream a text or thinking turn as dozens of small chunks, one `session/update` each. Buffering\n  // consecutive same-typed chunks into one event cuts that to about one a second, in the order they arrived; anything\n  // else (a tool call, the run ending) flushes what is pending first, so order never changes.\n  let pendingChunk: { type: 'text' | 'thinking'; content: string } | undefined;\n  let pendingTimer: ReturnType<typeof setTimeout> | undefined;\n  const flushLegacyChunk = (): void => {\n    if (pendingTimer !== undefined) {\n      clearTimeout(pendingTimer);\n      pendingTimer = undefined;\n    }\n    if (!pendingChunk) return;\n    const chunk = pendingChunk;\n    pendingChunk = undefined;\n    emit({ type: chunk.type, content: chunk.content });\n  };\n  const emitLegacyChunk = (type: 'text' | 'thinking', text: string): void => {\n    if (replaying || finished) return;\n    pendingChunk =\n      pendingChunk && pendingChunk.type === type\n        ? { type, content: pendingChunk.content + text }\n        : (flushLegacyChunk(), { type, content: text });\n    if (pendingChunk.content.length >= MERGE_FLUSH_BYTES) {\n      flushLegacyChunk();\n      return;\n    }\n    pendingTimer ??= setTimeout(flushPendingChunk, MERGE_FLUSH_MS);\n  };\n  const flushPendingChunk = () =>\n    session.outputBlocks ? flushStreamChunk() : flushLegacyChunk();\n  const emitChunk = (type: 'text' | 'thinking', text: string) =>\n    session.outputBlocks\n      ? emitStreamChunk(type, text)\n      : emitLegacyChunk(type, text);\n  const update = ({ update }: SessionNotification): void => {\n    if (replaying) return;\n    if (\n      (update.sessionUpdate === 'agent_message_chunk' ||\n        update.sessionUpdate === 'agent_thought_chunk') &&\n      update.content.type === 'text'\n    ) {\n      const text = update.content.text;\n      if (update.sessionUpdate === 'agent_message_chunk')\n        summary = (summary + text).slice(-64 * 1024);\n      emitChunk(\n        update.sessionUpdate === 'agent_message_chunk' ? 'text' : 'thinking',\n        text,\n      );\n    } else if (\n      update.sessionUpdate === 'tool_call' ||\n      update.sessionUpdate === 'tool_call_update'\n    ) {\n      flushPendingChunk();\n      const previous = toolCalls.get(update.toolCallId);\n      const call = {\n        name: update.title ?? previous?.name ?? 'Tool',\n        input: update.rawInput ?? previous?.input,\n        finished: previous?.finished ?? false,\n      };\n      if (!previous)\n        emit({\n          type: 'toolUse',\n          tool: call.name,\n          input: call.input,\n          meta: { toolUseId: update.toolCallId },\n        });\n      if (\n        !call.finished &&\n        (update.status === 'completed' || update.status === 'failed')\n      ) {\n        call.finished = true;\n        const output =\n          update.rawOutput === undefined\n            ? JSON.stringify(update.content ?? [])\n            : typeof update.rawOutput === 'string'\n              ? update.rawOutput\n              : JSON.stringify(update.rawOutput);\n        emit({\n          type: 'toolResult',\n          tool: call.name,\n          output,\n          meta: {\n            toolUseId: update.toolCallId,\n            isError: update.status === 'failed',\n          },\n        });\n      }\n      toolCalls.set(update.toolCallId, call);\n    } else if (update.sessionUpdate === 'plan') {\n      flushPendingChunk();\n      emit({\n        type: 'status',\n        content: 'plan',\n        meta: { plan: capInput(update.entries).input },\n      });\n    } else if (\n      ['config_option_update', 'current_mode_update', 'usage_update'].includes(\n        update.sessionUpdate,\n      )\n    ) {\n      flushPendingChunk();\n      emit({\n        type: 'status',\n        content: update.sessionUpdate,\n        meta: { update: capInput(update).input },\n      });\n      // How full the context window is, the same event every runner reports it as.\n      if (\n        update.sessionUpdate === 'usage_update' &&\n        typeof (update as { used?: unknown }).used === 'number' &&\n        typeof (update as { size?: unknown }).size === 'number' &&\n        (update as { size: number }).size > 0\n      )\n        emit({\n          type: 'status',\n          content: 'context',\n          meta: {\n            context: {\n              used: (update as { used: number }).used,\n              size: (update as { size: number }).size,\n            },\n          },\n        });\n    }\n  };\n  let stopping: Promise<void> | undefined;\n  const stop = (): Promise<void> =>\n    (stopping ??= (async () => {\n      cancelled = true;\n      if (process && sessionId) {\n        // Cancellation is a notification, followed by a bounded grace period for the turn to settle.\n        void process.agent\n          .notify(methods.agent.session.cancel, { sessionId })\n          .catch(() => {});\n        await Promise.race([\n          result.then(() => {}),\n          new Promise<void>((resolve) => setTimeout(resolve, 1500)),\n        ]);\n      }\n      opening.abort();\n      await process?.stop();\n    })());\n  const aborted = (): void => {\n    void stop();\n  };\n  session.abort.addEventListener('abort', aborted, { once: true });\n  const result: Promise<AdapterResult> = (async () => {\n    try {\n      session.abort.throwIfAborted();\n      const resolved = await resolveAgent(spec, session.env);\n      if (!resolved)\n        throw new Error('The selected coding tool is not installed.');\n      process = await AgentProcess.start(resolved, {\n        cwd: session.workDir,\n        env: session.env,\n        client: CLIENT,\n        signal: opening.signal,\n        handlers: {\n          update,\n          permission: async (request, signal) => {\n            if (cancelled || signal.aborted)\n              return { outcome: { outcome: 'cancelled' } };\n            const decision = await session.permission(\n              request.toolCall.title ?? 'Tool',\n              { input: request.toolCall.rawInput },\n            );\n            if (cancelled || signal.aborted)\n              return { outcome: { outcome: 'cancelled' } };\n            flushPendingChunk();\n            const option =\n              decision === 'allow'\n                ? (request.options.find(\n                    (item) => item.kind === 'allow_always',\n                  ) ??\n                  request.options.find((item) => item.kind === 'allow_once'))\n                : (request.options.find(\n                    (item) => item.kind === 'reject_once',\n                  ) ??\n                  request.options.find(\n                    (item) => item.kind === 'reject_always',\n                  ));\n            emit({\n              type: 'permission',\n              tool: request.toolCall.title ?? 'Tool',\n              input: request.toolCall.rawInput,\n              meta: { decision: decision === 'allow' ? 'allow' : 'deny' },\n            });\n            return {\n              outcome: option\n                ? { outcome: 'selected', optionId: option.optionId }\n                : { outcome: 'cancelled' },\n            };\n          },\n        },\n      });\n      const resumed = session.resumeSessionId\n        ? await continueSession(\n            process,\n            session.resumeSessionId,\n            session.workDir,\n            (active) => {\n              replaying = active;\n            },\n          )\n        : undefined;\n      if (session.resumeSessionId && !resumed)\n        requireRecoverableSession(session);\n      const opened =\n        resumed ??\n        (await process.agent.request(methods.agent.session.new, {\n          cwd: session.workDir,\n          mcpServers: [],\n        }));\n      sessionId = resumed\n        ? session.resumeSessionId\n        : 'sessionId' in opened\n          ? String(opened.sessionId)\n          : undefined;\n      if (!sessionId) throw new Error('The agent did not return a session id.');\n      if (session.resumeSessionId && !resumed) {\n        flushPendingChunk();\n        emit({\n          type: 'status',\n          content: 'sessionRecovery',\n          meta: { reason: 'The agent could not continue the earlier session.' },\n        });\n      }\n      await configureSession(process, sessionId, opened, spec, session.model);\n      if (cancelled) return { exit: 'aborted', usage: [], sessionId };\n      const response = await process.agent.request(\n        methods.agent.session.prompt,\n        {\n          sessionId,\n          prompt: [\n            { type: 'text', text: session.systemPrompt },\n            ...(session.skills\n              ? [\n                  {\n                    type: 'text' as const,\n                    text: `Read the provided skills in ${session.skills.dir}: ${session.skills.slugs.join(', ')}.`,\n                  },\n                ]\n              : []),\n            { type: 'text', text: session.prompt },\n          ],\n        },\n      );\n      const usage = response.usage\n        ? [\n            {\n              tool: spec.id as AgentTool,\n              ...(session.model ? { model: session.model } : {}),\n              inputTokens: response.usage.inputTokens,\n              outputTokens: response.usage.outputTokens,\n              ...(response.usage.cachedReadTokens == null\n                ? {}\n                : { cacheReadTokens: response.usage.cachedReadTokens }),\n              ...(response.usage.cachedWriteTokens == null\n                ? {}\n                : { cacheWriteTokens: response.usage.cachedWriteTokens }),\n              ...(response.usage.thoughtTokens == null\n                ? {}\n                : { reasoningTokens: response.usage.thoughtTokens }),\n            },\n          ]\n        : [];\n      if (session.outputBlocks) flushStreamChunk();\n      else flushLegacyChunk();\n      if (usage.length) emit({ type: 'usage', meta: { usage } });\n      if (cancelled || response.stopReason === 'cancelled')\n        return { exit: 'aborted', usage, sessionId };\n      if (response.stopReason !== 'end_turn')\n        return {\n          exit: 'error',\n          usage,\n          sessionId,\n          error: {\n            reason:\n              response.stopReason === 'max_tokens'\n                ? 'contextOverflow'\n                : 'toolProcess',\n            message: `The agent stopped: ${response.stopReason}.`,\n          },\n        };\n      return { exit: 'completed', usage, sessionId, summary };\n    } catch (error) {\n      const unavailable = sessionUnavailable(error);\n      if (unavailable) return unavailable;\n      if (session.outputBlocks && cancelled) flushStreamChunk();\n      return {\n        exit: cancelled ? 'aborted' : 'error',\n        usage: [],\n        ...(sessionId ? { sessionId } : {}),\n        error: {\n          reason: isAuthRequired(error)\n            ? 'toolAuth'\n            : error instanceof ModelSelectionError\n              ? 'modelUnavailable'\n              : 'toolProcess',\n          message: isAuthRequired(error)\n            ? `${spec.name} requires login on the runner. Run ${spec.signIn} there, then detect again. (${runFailureMessage(error, 'no further detail from the tool.')})`\n            : error instanceof ModelSelectionError\n              ? error.message\n              : runFailureMessage(\n                  error,\n                  'The ACP agent could not complete the request.',\n                ),\n        },\n      };\n    } finally {\n      if (session.outputBlocks) flushStreamChunk(true);\n      else flushLegacyChunk();\n      session.abort.removeEventListener('abort', aborted);\n      await process?.stop();\n      finished = true;\n      events.close();\n    }\n  })();\n  return { events, result, steer: () => Promise.resolve(false), stop };\n}\n\nexport function acpSpec(id: string): AgentSpec | undefined {\n  return AGENTS.find((spec) => spec.id === id);\n}\n"
    },
    {
      "path": "packages/plugins/app-plugin-agents/server/core/runs/claim.ts",
      "content": "import { upgradeReservation } from './runner-affinity.js';\nimport { ACTIVE_JOB, jobsRepo } from '../../jobs/job.store.js';\n/**\n * Claiming: handing queued runs to a runner that fits them, within each agent's concurrency limit, one run per\n * (agent, subject, thread) at a time, through the runners' one long-poll (`routes/runners/runner.ts`), which hands\n * out jobs from the same slots. A runner fits a run when it has the agent's\n * tool enabled (on the web), installed and signed in, the agent names no runner or names it, it is shared with the\n * team or belongs to the person who woke the agent, its features cover what the run requires (worked out from the\n * payload: checkouts, directories, skills, secrets), its owner's local policy (`Runner.policy`) lets it take the\n * agent's runs on the run's subject and repositories, and it has a free slot. A working directory that is a directory\n * on one runner pins the run to that runner; multiple runs may share that directory. A run's variables go to the runner that\n * takes it, personal ones included, unless one of them is for shared runners only (`teamRunnersOnly`): then only a team\n * runner takes the run, and the variables that asked for one are noted on it (`teamOnlyVariables`), so its wait says\n * which.\n *\n * A slot is free for a run when the runner's total has room and so does the coding tool it runs with: the tool's limit\n * (`Runner.toolSlots`, never above the total) over the runs of that tool the runner holds here, and what the runner\n * said it can still take of that tool across every application (`ClaimRequest.tools`). The run takes the first of its\n * agent's entries whose tool the runner runs and has room for, so an agent listing two tools runs with the second while\n * the first is full; a run none of whose tools has room is passed over for the runs behind it.\n *\n * Runners share a queue in proportion to each tool's limit, not by who asks first: before it locks anything, a claim\n * waits until the run has been queued for the share of the tool's limit the runner already runs, times one second\n * (`claimPace`). The runners' route hands out one run per request and the runner asks again at once, so of several\n * runners woken for the same runs, the least busy with each tool takes the next one. A request that ends while it\n * waits takes nothing.\n *\n * Variables are checked and opened in the claim's own transaction, on its connection: which ones the assembled payload\n * gets, whether any is for shared runners only, and their values, so what the runner receives is what was checked. The\n * names taken from the runner go in `workspace.passthrough`, without values.\n *\n * A claim is one transaction per run. It first writes the agent's row (`lockAgentForClaim`): on databases with row\n * locks, concurrent claims for the same agent wait there, so the concurrency count read next is current. The run is\n * then taken with a guarded update (`status = 'queued'`), so two runners can never take the same run. The payload is\n * assembled in the same transaction; if assembly fails the transaction rolls back, the run stays queued, and the\n * failure is counted (`claimFailures`) until the run fails `setupFailed`.\n *\n * Portable by design: the database layer offers no `FOR UPDATE SKIP LOCKED` or advisory locks, and the guarded update\n * plus the agent-row write give the same guarantees on every dialect (SQLite serializes writers anyway).\n *\n * Polls are the hot path: every runner walks the same candidates, so a write per candidate is a write per candidate per\n * runner per poll. Everything that rules a candidate out is read outside any transaction — identity, `fits()`, slots,\n * concurrency and comment consent — and a transaction opens only for the run about to be claimed. The agent row is\n * the only row a claim locks with a self-update, and only in that final transaction after `fits()` (or when a stale\n * identity has to be repaired first, which current work never needs). PostgreSQL runs at READ COMMITTED, where each\n * statement sees the latest committed rows, so no transaction needs no-op writes to refresh a snapshot; comment\n * consent needs no chain lock, because confirmation is final and rejection or Run as me end the chain's queued runs,\n * which the guarded update sees. A new write or lock here needs a measured reason (`tests/claim-concurrency.test.ts`\n * counts them, and the lock waits on PostgreSQL).\n\n */\nimport { GLOBAL_SKILL_TARGET } from '../../../shared/skills.js';\n\nimport {\n  ANNOUNCED_FAILURES,\n  isProtocolSupported,\n  type AgentTool,\n  policyAllowsAgent,\n  policyAllowsRepo,\n  policyAllowsSubject,\n  TIMINGS,\n  type RunApp,\n  type RunInput,\n  type RunnerFeature,\n  type RunPayload,\n  type RunSkill,\n  type WorkspaceDir,\n} from '@nocobase/agent-protocol';\nimport type { DistService } from '../../distribution/index.js';\nimport {\n  chatEffortCapabilities,\n  quotaForAgent,\n  runnerLowOnDisk,\n  runsEntry,\n  toolLimit,\n  supportsWorkspaceKey,\n  type Runner,\n} from '../../../shared/runners.js';\nimport { queueStart, type ModelSelectionPolicies } from './selection.js';\nimport type { DatabaseConnection } from '@nocobase/db';\nimport type { Slots } from '../../runners/slots.js';\nimport { createHash } from 'node:crypto';\n\nimport type { Agent, RunnerModelEntry } from '../../../shared/agents.js';\nimport type { BriefLayers } from '../../../shared/briefs.js';\nimport type {\n  Run,\n  ModelSelectionWait,\n  ModelWaitReason,\n  RunExecutionSnapshot,\n} from '../../../shared/runs.js';\nimport { later, pause, type Clock } from '../../kernel/clock.js';\nimport { notFound } from '../../kernel/errors.js';\nimport type { People } from '../../kernel/people.js';\nimport type { IdSource } from '../../kernel/ids.js';\nimport { runSecretsKey, type SecretMemory } from '../../kernel/redaction.js';\nimport type { Tx, TxRunner } from '../../kernel/tx.js';\nimport { cleanList, covers, jsonObject } from '../../kernel/values.js';\nimport { findAgent, findAgents, lockAgentForClaim } from '../agents/index.js';\nimport { joinBrief, renderBrief } from '../brief/index.js';\nimport { cliPackageFor } from './cli-package.js';\nimport { executionHistory } from './execution.js';\nimport type { SkillService, SkillTarget } from '../skills/index.js';\nimport {\n  describeVariables,\n  variableRefs,\n  type RunVariables,\n  type VariableService,\n  type VariableTarget,\n} from '../variables/index.js';\nimport type { VariableRef } from '../../../shared/variables.js';\nimport {\n  mountsFor,\n  prepareExtensions,\n  repoAccessFor,\n  RepoAccessError,\n  responsibleOf,\n  type RepoAccessRegistry,\n  sessionKeyOf,\n  withSections,\n  type BriefSectionRegistry,\n  type Prepared,\n  type RunMountRegistry,\n} from './extensions.js';\nimport {\n  type ClaimContext,\n  type SubjectAssembly,\n  type SubjectDir,\n} from './ports.js';\nimport { MAX_CLAIM_FAILURES, toolPolicyFor, type AgentCli } from './policy.js';\nimport { mintRunToken } from './run-tokens.js';\nimport {\n  ACTIVE,\n  countActive,\n  eventsRepo,\n  findRunRecord,\n  markDelivered,\n  pendingInputs,\n  type InputRecord,\n  runsOfKey,\n  runsRepo,\n  inputsRepo,\n  sessionsRepo,\n  toInput,\n  toExecutions,\n  toRun,\n  type RunRecord,\n} from './run.store.js';\nimport { dropInputs } from './input-gate.js';\nimport { finishRun, type TransitionDeps } from './transitions.js';\nimport { queuedIdentityCurrent, refreshQueuedIdentity } from './identity.js';\nimport {\n  currentCommentOwner,\n  commentConsent,\n  commentFromOwner,\n  withdrawCommentRequests,\n} from './comment-consent.js';\nimport { insertRunRequest, runRequestsRepo } from './run-requests.js';\nimport { consumeReset, saveBrief } from './workspace.store.js';\n\n/** Ordinary queued runs per page, oldest first by priority. */\nconst CANDIDATES = 50;\n/** The initial page plus at most two further pages per claim request, shared by all free slots. */\nconst CANDIDATE_PAGES = 3;\n/** The longest a claim waits its turn: what a runner waits for a run when it already runs its tool at the limit. */\nconst PACE_MS = 1000;\n\n/** Request-local read budget, also shared by a long poll's post-wait check. */\nexport interface ClaimScan {\n  remainingPages: number;\n}\n\nexport function createClaimScan(): ClaimScan {\n  return { remainingPages: CANDIDATE_PAGES };\n}\n\nexport interface ClaimService {\n  reconcileCommentConsent(unit: Tx, runId: string): Promise<void>;\n  reconcileCommentQueue(): Promise<void>;\n  /** Structured ordered-model diagnostics; machine visibility is enforced by the caller. */\n  selectionWait(runId: string): Promise<ModelSelectionWait | null>;\n  /** Read-only capacity and compatibility for a real subject and candidate agent, as the run's actor. */\n  diagnose(\n    conn: DatabaseConnection,\n    run: Run,\n    agent: Agent,\n  ): Promise<ModelSelectionWait | null>;\n  /**\n   * Up to `free` runs for `runner`, each with its payload; empty when nothing fits. `tools` is what the runner said it\n   * can take of each coding tool it keeps a limit for (`ClaimRequest.tools`); a tool left out is bounded by `free`.\n   * A request-local `scan` shares the page cap with a long poll's post-wait check. Each run is taken no earlier than\n   * `claimPace` says, waited out before any lock; when `signal` aborts meanwhile, the claim ends with what it took.\n   */\n  claim(\n    runner: Runner,\n    free: number,\n    tools?: Readonly<Partial<Record<AgentTool, number>>>,\n    scan?: ClaimScan,\n    signal?: AbortSignal,\n  ): Promise<RunPayload[]>;\n  /** The skills a run gets, worked out the way its claim works them out. The caller checks who holds the run. */\n  runSkills(runner: Runner, runId: string): Promise<RunSkill[]>;\n}\n\nexport interface ClaimDeps extends TransitionDeps {\n  readonly selectionPolicies?: ModelSelectionPolicies;\n  readonly runners?: {\n    online(conn: DatabaseConnection): Promise<Runner[]>;\n    all(conn: DatabaseConnection, ids?: readonly string[]): Promise<Runner[]>;\n  };\n  readonly people?: Pick<People, 'names'>;\n  readonly tx: TxRunner;\n  readonly ids: IdSource;\n  readonly clock: Clock;\n  readonly variables: VariableService;\n  readonly skills: SkillService;\n  /** Where the CLI fetches its manifest, as runners see the server. */\n  readonly manifestUrl: string;\n  /** Who hands out the runs. */\n  readonly app: RunApp;\n  /** The application CLI runs get: its name, where the runner finds it, and its credentials file. */\n  readonly cli: AgentCli;\n  /** The tarballs the application serves, for a `served` CLI. */\n  readonly dist?: Pick<DistService, 'find'>;\n  /** What a runner holds now (its slots); runs and jobs share them. */\n  readonly slotsHeld: Slots['held'];\n  /** How a claim waits its turn (`claimPace`); real timers when left out. */\n  readonly pause?: (ms: number, signal?: AbortSignal) => Promise<void>;\n  /** Sections the application adds to every brief's context layer. */\n  readonly sections?: BriefSectionRegistry;\n  /** Directories of files the application places beside the agent, for runners with the `mounts` feature. */\n  readonly mounts?: RunMountRegistry;\n  /** Who a run's commits name and what its checkouts push with. */\n  readonly repoAccess?: RepoAccessRegistry;\n  /** Remembers the secrets a claim hands out, so what the run reports is redacted of them (`kernel/redaction.ts`). */\n  readonly secrets?: SecretMemory;\n  readonly onClaimFailure?: (runId: string, error: unknown) => void;\n}\n\nclass AssemblyError extends Error {\n  public constructor(\n    message: string,\n    public readonly cause: unknown,\n  ) {\n    super(message);\n    this.name = 'AssemblyError';\n  }\n}\n\n/** The run does not fit this runner after all (its payload needs another runner or unavailable capabilities). */\nclass NotForThisRunner extends Error {\n  public constructor() {\n    super('The run does not fit this runner.');\n    this.name = 'NotForThisRunner';\n  }\n}\n\n/** The run gets variables only shared runners may receive, and this runner is a personal one. */\nclass TeamRunnersOnly extends NotForThisRunner {\n  public constructor(public readonly variables: readonly VariableRef[]) {\n    super();\n    this.name = 'TeamRunnersOnly';\n  }\n}\n\n/** What a runner said it can still take of each coding tool during one claim, counted down as runs are handed out. */\ninterface ToolRoom {\n  has(tool: AgentTool): boolean;\n  take(tool: AgentTool): void;\n}\n\nfunction toolRoom(\n  tools: Readonly<Partial<Record<AgentTool, number>>> | undefined,\n): ToolRoom {\n  const left = new Map<AgentTool, number>(\n    Object.entries(tools ?? {}) as [AgentTool, number][],\n  );\n  return {\n    has: (tool) => (left.get(tool) ?? Number.POSITIVE_INFINITY) > 0,\n    take: (tool) => {\n      const count = left.get(tool);\n      if (count !== undefined) left.set(tool, count - 1);\n    },\n  };\n}\n\ntype Attempt =\n  | { readonly kind: 'claimed'; readonly payload: RunPayload }\n  | { readonly kind: 'skipped' }\n  /** The request went away while the claim waited its turn: nothing more is taken. */\n  | { readonly kind: 'aborted' }\n  /** Nothing else of this agent (`agent`) or for this runner (`runner`) can be claimed in this pass. */\n  | { readonly kind: 'full'; readonly scope: 'agent' | 'runner' };\n\n/** What one claim pass knows before any lock: the runs `runner` holds by tool, and the request it answers. */\ninterface ClaimPass {\n  readonly byTool: Readonly<Partial<Record<AgentTool, number>>>;\n  readonly signal?: AbortSignal;\n}\n\n/**\n * How long `runner` waits before it takes `run` with `tool`, at `now`: the share of the tool's limit it already runs\n * (`toolLimit`), of the busier of what this application counts (`byTool`) and what the runner last reported\n * (`Runner.toolLoad`), times one second, counted from when the run entered the queue (`queueStart`). Several runners\n * woken for one run take it in order of how busy each is with its tool, whichever asked first and however many runs\n * each took before; an idle runner, and work queued longer than its share, wait nothing.\n */\nexport function claimPace(\n  runner: Pick<Runner, 'slots' | 'toolSlots' | 'toolLoad'>,\n  tool: AgentTool,\n  byTool: Readonly<Partial<Record<AgentTool, number>>>,\n  run: Pick<Run, 'queueEnteredAt' | 'createdAt' | 'availableAt'>,\n  now: number,\n): number {\n  const limit = toolLimit(runner, tool);\n  if (limit <= 0) return 0;\n  const load = runner.toolLoad?.[tool];\n  const used = Math.max(byTool[tool] ?? 0, load ? load.slots - load.free : 0);\n  const share = (Math.min(used, limit) / limit) * PACE_MS;\n  return Math.min(share, Math.max(0, queueStart(run) + share - now));\n}\n\n/**\n * The entry `runner` takes a run of `agent` with: the first whose tool it has enabled, installed and signed in, with\n * the entry's model among those it reports (`runsEntry`). Null when it has none of them.\n */\nexport function pickEntry(\n  runner: Runner,\n  agent: Pick<Agent, 'modelEntries'>,\n  now: number,\n): RunnerModelEntry | null {\n  return (\n    agent.modelEntries.find((entry) => runsEntry(runner, entry, now)) ?? null\n  );\n}\n\n/**\n * The entry `runner` takes a run of `agent` with when some of its tools are full: the first whose tool it runs and\n * `open` says has room. Null when none has.\n */\nexport function pickOpenEntry(\n  runner: Runner,\n  agent: Pick<Agent, 'modelEntries'>,\n  open: (tool: AgentTool) => boolean,\n  now: number,\n): RunnerModelEntry | null {\n  return (\n    agent.modelEntries.find(\n      (entry) => runsEntry(runner, entry, now) && open(entry.tool),\n    ) ?? null\n  );\n}\n\n/** Whether `runner` has one of `agent`'s tools and models enabled, installed, signed in and reported. */\nexport function hasTool(\n  runner: Runner,\n  agent: Pick<Agent, 'modelEntries'>,\n  now: number,\n): boolean {\n  return pickEntry(runner, agent, now) !== null;\n}\n\n/**\n * Whether `runner` may run work of `agent` as `actorUserId` that needs `requires`, before any lock is taken and before\n * a payload is known: the agent enabled, its tool and model reported there, its owner's policy, and trust.\n */\nexport function fitsActor(\n  runner: Runner,\n  agent: Agent,\n  actorUserId: string,\n  requires: readonly RunnerFeature[],\n  now: number,\n): boolean {\n  if (agent.status !== 'enabled' || runnerLowOnDisk(runner)) return false;\n  if (\n    !isProtocolSupported(runner.protocolVersion) ||\n    runner.status === 'upgrade_required' ||\n    runner.status === 'revoked'\n  )\n    return false;\n  if (!covers(runner.features, requires)) return false;\n  if (!hasTool(runner, agent, now)) return false;\n  if (!policyAllowsAgent(runner.policy, agent)) return false;\n  return runner.trust === 'team' || runner.ownerUserId === actorUserId;\n}\n\n/** A strict continuation keeps the tool/model that owns its original session. */\nfunction quotaAgent(run: RunRecord, agent: Agent): Agent {\n  if (!run.runnerPinId || run.freshSession) return agent;\n  const last = toExecutions(run.executionHistory).at(-1);\n  const tool = last?.tool ?? run.tool;\n  const model = last ? last.model : run.model;\n  return tool\n    ? {\n        ...agent,\n        modelEntries: agent.modelEntries.filter(\n          (entry) => entry.tool === tool && entry.model === model,\n        ),\n      }\n    : agent;\n}\n\n/** Whether `runner` may run `run` of `agent`, before any lock is taken and before its payload is known. */\nexport function fits(\n  runner: Runner,\n  agent: Agent,\n  run: RunRecord,\n  now: number,\n): boolean {\n  return (\n    (!run.runnerPinId || run.runnerPinId === runner.id) &&\n    fitsActor(\n      runner,\n      quotaAgent(run, agent),\n      run.actorUserId,\n      toRun(run).requires,\n      now,\n    )\n  );\n}\n\n/** The runner features a payload needs. */\nexport function payloadRequires(\n  dirs: readonly WorkspaceDir[],\n  skills: number,\n  variables: number,\n  workspaceKey: boolean = false,\n): RunnerFeature[] {\n  return [\n    ...(workspaceKey ? ['workspaceKey' as const] : []),\n    ...(dirs.some((dir) => dir.kind === 'repo') ? ['checkout' as const] : []),\n    ...(dirs.some((dir) => dir.kind === 'directory')\n      ? ['directories' as const]\n      : []),\n    ...(skills > 0 ? ['skills' as const] : []),\n    ...(variables > 0 ? ['secrets' as const] : []),\n  ];\n}\n\n/** The working directories as a runner receives them: without what only the server uses. */\nexport function payloadDirs(dirs: readonly SubjectDir[]): WorkspaceDir[] {\n  return dirs.map((dir): WorkspaceDir => {\n    const { scopeId: _scope, runnerId: _runner, ...rest } = dir;\n    return rest;\n  });\n}\n\n/** Where a run's variables come from, in merge order: the subject's scopes, its directories', the agent's. */\nexport function variableTargets(\n  agent: Pick<Agent, 'id'>,\n  assembly: Pick<SubjectAssembly, 'scopes' | 'dirs'>,\n): VariableTarget[] {\n  return [\n    ...assembly.scopes,\n    ...assembly.dirs.flatMap((dir) =>\n      dir.scopeId ? [{ scope: 'workdir', scopeId: dir.scopeId }] : [],\n    ),\n    { scope: 'agent', scopeId: agent.id },\n  ];\n}\n\n/** Team defaults, application scopes and directories, from lowest to highest priority. */\nexport function skillTargets(\n  _agent: Pick<Agent, 'id'>,\n  assembly: Pick<SubjectAssembly, 'scopes' | 'dirs'>,\n): SkillTarget[] {\n  return [\n    GLOBAL_SKILL_TARGET,\n    ...assembly.scopes.filter(\n      (target) => target.scope !== 'agent' && target.scope !== 'global',\n    ),\n    ...assembly.dirs.flatMap((dir) =>\n      dir.scopeId ? [{ scope: 'workdir', scopeId: dir.scopeId }] : [],\n    ),\n  ];\n}\n\nfunction fingerprint(\n  agent: Agent,\n  entry: RunnerModelEntry,\n  layers: Pick<BriefLayers, 'system' | 'agent'>,\n  skills: readonly { readonly slug: string; readonly hash: string }[],\n  readOnly: boolean,\n): string {\n  return createHash('sha256')\n    .update(\n      JSON.stringify([\n        entry.tool,\n        entry.model,\n        agent.instructions,\n        layers.system,\n        layers.agent,\n        skills.map((skill) => [skill.slug, skill.hash]),\n        // Keep existing writable fingerprints unchanged across upgrades.\n        ...(readOnly ? [{ readOnly: true }] : []),\n      ]),\n    )\n    .digest('hex');\n}\n\n/** The brief of a run on a subject, as the claim renders it; the preview renders it the same way. */\nexport interface RenderedBrief {\n  readonly layers: BriefLayers;\n  readonly turn: string;\n  readonly prompt: string;\n}\n\n/** The brief for `assembly`, with the skills a run would get. */\nexport function briefOf(\n  agent: Agent,\n  assembly: SubjectAssembly,\n  skills: readonly {\n    readonly slug: string;\n    readonly name: string;\n    readonly description: string;\n  }[],\n  cli: string,\n  appName: string,\n): RenderedBrief {\n  // Custom system prompts (such as conversations) keep their own layout.\n  const stablePrefix =\n    assembly.briefLayout === 'stable-prefix' && assembly.system === undefined;\n  const input = {\n    agentName: agent.name,\n    subject: { noun: assembly.subject.noun, key: assembly.subject.key },\n    task: assembly.task,\n    context: assembly.context,\n    instructions: agent.instructions,\n    dirs: payloadDirs(assembly.dirs),\n    skills,\n    cli,\n    appName,\n    ...(assembly.guidance ? { guidance: assembly.guidance } : {}),\n  };\n  const rendered = renderBrief(input);\n  const layers =\n    assembly.system === undefined\n      ? rendered\n      : { ...rendered, system: assembly.system };\n  const turn = assembly.turn.previousSummary\n    ? `${assembly.turn.prompt}\\n\\nWhat earlier runs on this already did:\\n\\n${assembly.turn.previousSummary}`\n    : assembly.turn.prompt;\n  // Keep the logical layers (and their session fingerprint) unchanged. Only the outgoing text is reordered,\n  // so an ordinary follow-up can still resume the session created by an independent review.\n  const prompt = stablePrefix\n    ? joinBrief(renderBrief({ ...input, stablePrefix: true }), true)\n    : joinBrief(layers);\n  return { layers, turn, prompt };\n}\n\n/** What a claim produces: the payload, the run's requirements and directories, and the brief's fingerprint. */\ninterface Assembled {\n  readonly payload: RunPayload;\n  readonly fingerprint: string;\n  readonly requires: readonly RunnerFeature[];\n  readonly directoryKey: string | null;\n  readonly entry: RunnerModelEntry;\n  /** The repositories the runner asks credentials for on demand (`RunGit.onDemand`). */\n  readonly gitOnDemand: readonly string[];\n}\n\n/** Whether `runner` asks for repository credentials on demand rather than taking them with the claim. */\nexport function asksCredentialsOnDemand(\n  runner: Pick<Runner, 'features'>,\n): boolean {\n  return runner.features.includes('gitCredentials');\n}\n\n/** Where a claim keeps the subject's responsible it read before its transaction (`Prepared`). */\nconst RESPONSIBLE_KEY = 'claim:responsibleUserId';\n\nfunction responsibleIn(prepared: Prepared): string | null {\n  const value = prepared.get(RESPONSIBLE_KEY);\n  return typeof value === 'string' ? value : null;\n}\n\n/** Whether `runner` wraps code host CLIs with the run's credential (`RunGit.tools`). */\nexport function wrapsHostTools(runner: Pick<Runner, 'features'>): boolean {\n  return runner.features.includes('gitTools');\n}\n\nconst DIRECTORY_KEY_SEPARATOR = '\\n';\n\n/** The directories a run holds on its runner, as stored in `agRuns.directoryKey`. */\nfunction directoryKeyOf(\n  runnerId: string,\n  dirs: readonly WorkspaceDir[],\n): string | null {\n  const paths = dirs\n    .filter((dir) => dir.kind === 'directory')\n    .map((dir) => `${runnerId}:${dir.path}`);\n  return paths.length > 0 ? paths.join(DIRECTORY_KEY_SEPARATOR) : null;\n}\n\n/** Resolve omitted subject input in the claim transaction, keeping it in the audit history. */\nasync function settleClaimInputs(\n  conn: DatabaseConnection,\n  pending: readonly InputRecord[],\n  effective: readonly RunInput[],\n  now: string,\n): Promise<void> {\n  const ids = new Set(effective.map((input) => input.id));\n  await dropInputs(\n    conn,\n    pending.filter((input) => !ids.has(input.id)).map((input) => input.id),\n    now,\n  );\n  const given = pending.filter((input) => ids.has(input.id));\n  const delivered = await markDelivered(conn, given, now);\n  // One was withdrawn while the claim assembled it: claim the run again, without it.\n  if (delivered.length !== given.length) throw new NotForThisRunner();\n}\n\nexport function createClaimService(deps: ClaimDeps): ClaimService {\n  const { tx, clock } = deps;\n\n  /** Reuse only identical ordered targets, within this attempt and connection. */\n  function claimResources(conn: DatabaseConnection, runId: string) {\n    const cache = new Map<\n      string,\n      Promise<{\n        skills: RunSkill[];\n        variables: RunVariables;\n      }>\n    >();\n    return (agent: Agent, assembly: SubjectAssembly) => {\n      const skills = skillTargets(agent, assembly);\n      const variables = variableTargets(agent, assembly);\n      const key = JSON.stringify([skills, variables]);\n      let result = cache.get(key);\n      if (!result) {\n        result = (async () => ({\n          skills: await deps.skills.forRun(conn, skills, runId),\n          variables: await deps.variables.prepareRun(conn, variables),\n        }))();\n        cache.set(key, result);\n      }\n      return result;\n    };\n  }\n\n  /** Database reads only; used by the actual claim and ordered-model diagnostics. */\n  async function assemblyCompatibility(\n    conn: DatabaseConnection,\n    run: Run,\n    agent: Agent,\n    runner: Runner,\n    assembly: SubjectAssembly,\n    resources = claimResources(conn, run.id),\n  ): Promise<'ready' | 'incompatible' | 'restricted'> {\n    if (\n      !isProtocolSupported(runner.protocolVersion) ||\n      (assembly.workspaceKey && !supportsWorkspaceKey(runner))\n    )\n      return 'incompatible';\n    const { skills, variables } = await resources(agent, assembly);\n    return compatibleAssembly(\n      run,\n      agent,\n      runner,\n      assembly,\n      skills.length,\n      variables,\n    );\n  }\n\n  function compatibleAssembly(\n    run: Run,\n    agent: Agent,\n    runner: Runner,\n    assembly: SubjectAssembly,\n    skillCount: number,\n    variables: Pick<RunVariables, 'names' | 'teamOnly'>,\n  ): 'ready' | 'incompatible' | 'restricted' {\n    if (\n      !isProtocolSupported(runner.protocolVersion) ||\n      (assembly.workspaceKey && !supportsWorkspaceKey(runner))\n    )\n      return 'incompatible';\n    const names = variables.names;\n    if (\n      !covers(runner.features, [\n        ...run.requires,\n        ...payloadRequires(\n          payloadDirs(assembly.dirs),\n          skillCount,\n          names.length,\n          Boolean(assembly.workspaceKey),\n        ),\n      ])\n    )\n      return 'incompatible';\n    if (\n      !fitsActor(\n        runner,\n        agent,\n        run.actorUserId,\n        run.requires,\n        clock.now().getTime(),\n      ) ||\n      !policyAllowsSubject(runner.policy, assembly.subject.key) ||\n      assembly.dirs.some(\n        (dir) =>\n          (dir.kind === 'repo' && !policyAllowsRepo(runner.policy, dir.url)) ||\n          (dir.kind === 'directory' && dir.runnerId !== runner.id),\n      )\n    )\n      return 'restricted';\n    if (runner.trust !== 'team' && variables.teamOnly.length > 0)\n      return 'restricted';\n    return 'ready';\n  }\n\n  async function selectionFacts(\n    conn: DatabaseConnection,\n    run: Run,\n    agent: Agent,\n    requirePolicy = true,\n    trust?: 'team' | 'personal',\n    resources = claimResources(conn, run.id),\n  ): Promise<ModelSelectionWait | null> {\n    const policy = await deps.selectionPolicies?.forRun(conn, run);\n    if ((requirePolicy && !policy) || !deps.runners) return null